window.EXAM_DATA = {"1": {"title": "Đề mô phỏng SAA-C03 — Bộ 01", "minutes": 130, "passScore": 720, "questions": [{"n": 1, "text": "A company uses AWS Organizations with multiple OUs. The security team must ensure that no account, including member account administrators, can disable AWS CloudTrail or leave the organization. Which solution meets this requirement with the LEAST operational overhead?", "options": {"A": "Attach an SCP to the root of the organization that explicitly denies cloudtrail:StopLogging, cloudtrail:DeleteTrail, and organizations:LeaveOrganization.", "B": "Create an IAM policy in each member account that denies those actions and attach it to all administrator roles.", "C": "Use AWS Config rules in each account to detect when CloudTrail is disabled and automatically re-enable it.", "D": "Remove administrator access from all member accounts and require all changes through the management account."}, "answers": ["A"], "multi": false, "explanation": "SCP áp ở root/OU có hiệu lực trên mọi account thành viên và ngay cả admin trong account cũng không vượt qua được SCP, nên đây là cách chặn triệt để với ít công vận hành nhất. B sai vì IAM policy trong từng account có thể bị admin sửa/xóa. C chỉ phát hiện và sửa sau, không ngăn chặn. D phá vỡ mô hình quản trị và không thực tế.", "keyword": "SCP deny > IAM policy, SCP applies to member admins"}, {"n": 2, "text": "A production application uses Amazon RDS for MySQL in a single Availability Zone. During an AZ failure, the application was unavailable for over an hour. The company needs automatic failover with no data loss for synchronous replication and minimal application changes. What should a solutions architect recommend?", "options": {"A": "Create a read replica in another Availability Zone and promote it manually when a failure occurs.", "B": "Enable Multi-AZ DB instance deployment with a standby in a different Availability Zone.", "C": "Take hourly EBS snapshots and restore the database in another Availability Zone during a failure.", "D": "Migrate to Amazon DynamoDB with global tables."}, "answers": ["B"], "multi": false, "explanation": "Multi-AZ DB instance dùng replication đồng bộ sang standby ở AZ khác và tự động failover, không mất dữ liệu, endpoint giữ nguyên nên app ít phải sửa. A là read replica (bất đồng bộ, phải promote thủ công, có thể mất dữ liệu). C là restore thủ công, RTO cao. D đổi cả engine, không cần thiết.", "keyword": "Multi-AZ = HA + synchronous + auto failover"}, {"n": 3, "text": "A company stores 500 TB of image archives in Amazon S3 Standard. The images are accessed frequently in the first 30 days, rarely after 90 days, and must be retrievable within a few hours after 1 year for compliance. The company wants the MOST cost-effective storage strategy.", "options": {"A": "Keep all objects in S3 Standard for their entire lifecycle.", "B": "Use an S3 Lifecycle policy to transition objects to S3 Standard-IA after 30 days, to S3 Glacier Flexible Retrieval after 90 days, and expire them after 7 years.", "C": "Use an S3 Lifecycle policy to transition objects to S3 One Zone-IA after 30 days and delete them after 90 days.", "D": "Copy all objects to S3 Glacier Deep Archive immediately after upload."}, "answers": ["B"], "multi": false, "explanation": "Lifecycle chuyển dần Standard → Standard-IA → Glacier Flexible Retrieval đúng với tần suất truy cập giảm dần và yêu cầu lấy lại trong vài giờ, tối ưu chi phí theo thời gian. A giữ Standard mãi nên đắt. C dùng One Zone-IA kém durable và xóa sau 90 ngày sai yêu cầu compliance. D đưa ngay vào Deep Archive khiến 30 ngày đầu truy cập chậm/đắt.", "keyword": "S3 Lifecycle, Glacier Flexible Retrieval = hours"}, {"n": 4, "text": "An application uses Amazon RDS for PostgreSQL. Read queries for reporting are slowing down the primary database and increasing CPU to 95%. The reporting workload can tolerate a few seconds of replication lag and must not affect write performance. What is the MOST appropriate solution?", "options": {"A": "Enable Multi-AZ deployment to offload reads to the standby instance.", "B": "Create an Amazon RDS read replica and direct reporting queries to the replica endpoint.", "C": "Increase the DB instance class to a larger size.", "D": "Enable RDS storage autoscaling."}, "answers": ["B"], "multi": false, "explanation": "Read replica dùng replication bất đồng bộ để offload read, chấp nhận lag vài giây, không ảnh hưởng write ở primary — đúng bản chất bài toán reporting. A sai vì standby Multi-AZ không đọc được. C tăng size chỉ tốn tiền và không tách tải triệt để. D storage autoscaling chỉ lo dung lượng, không lo CPU read.", "keyword": "Read Replica = scale read, Multi-AZ ≠ read"}, {"n": 5, "text": "A company must encrypt data in Amazon S3 using keys it can audit and control. The security team needs automatic annual rotation of the key material and a CloudTrail log of every key usage. Which solution meets these requirements?", "options": {"A": "Use S3-managed keys (SSE-S3) with bucket policies.", "B": "Use an AWS KMS customer managed key with automatic key rotation enabled for server-side encryption (SSE-KMS).", "C": "Use client-side encryption with keys stored in an on-premises server.", "D": "Use SSE-C with customer-provided keys sent on each request."}, "answers": ["B"], "multi": false, "explanation": "KMS customer managed key cho phép kiểm soát policy, audit qua CloudTrail và bật automatic rotation hằng năm, đáp ứng cả 3 yêu cầu. A SSE-S3 do AWS quản lý key, không kiểm soát/audit chi tiết được. C client-side + key on-prem vận hành nặng và không tích hợp S3 như yêu cầu. D SSE-C phải gửi key mỗi request, không có rotation/audit tập trung của KMS.", "keyword": "SSE-KMS, customer managed key, auto rotation"}, {"n": 6, "text": "A global media company serves static images and videos from Amazon S3 through Amazon CloudFront. Origin requests are still high and users in Asia report slow load times for popular content that rarely changes. Which change will MOST improve performance and reduce origin load?", "options": {"A": "Increase the CloudFront default TTL and configure cache policies to cache popular objects longer at edge locations.", "B": "Move the S3 bucket to a Region in Asia.", "C": "Enable S3 Transfer Acceleration on the bucket.", "D": "Add a second S3 bucket and use Route 53 latency-based routing."}, "answers": ["A"], "multi": false, "explanation": "Tăng TTL/cache policy đúng cách giúp object phổ biến, ít thay đổi được giữ lâu ở edge, giảm origin request và latency cho user châu Á. B chuyển Region chỉ giúp một khu vực và gây xáo trộn. C Transfer Acceleration tối ưu upload vào S3, không phải cache phân phối nội dung. D thêm bucket + latency routing vẫn phải về origin mỗi lần.", "keyword": "CloudFront TTL / cache policy = reduce origin load"}, {"n": 7, "text": "A company runs a web application on EC2 instances in Region us-east-1 with a standby environment in eu-west-1. If the primary Region fails, traffic must automatically move to the standby within minutes, based on health checks. Which Route 53 configuration should be used?", "options": {"A": "Simple routing policy with a health check on the primary endpoint.", "B": "Weighted routing policy with weights 100 for primary and 0 for standby.", "C": "Failover routing policy with health checks, primary record pointing to us-east-1 and secondary record pointing to eu-west-1.", "D": "Latency-based routing policy with health checks on both endpoints."}, "answers": ["C"], "multi": false, "explanation": "Failover routing policy sinh ra đúng cho primary/secondary, kết hợp health check để tự động chuyển DNS sang secondary khi primary unhealthy. A simple routing không có cơ chế failover. B weighted 100/0 không tự chuyển khi primary chết. D latency routing chọn nơi gần nhất, không phải cơ chế primary-standby.", "keyword": "Route 53 Failover routing + health check"}, {"n": 8, "text": "A batch processing job runs for 3 hours every night, can be interrupted and resumed without data loss, and currently runs on On-Demand EC2 instances. The company wants to reduce compute cost as much as possible for this workload. Which purchasing option should be used?", "options": {"A": "Standard Reserved Instances for 3 years, all upfront.", "B": "Convertible Reserved Instances for 1 year.", "C": "EC2 Spot Instances with a Spot Fleet and multiple instance types.", "D": "Dedicated Hosts."}, "answers": ["C"], "multi": false, "explanation": "Job chịu được gián đoạn và resume được là hồ sơ kinh điển của Spot, giảm giá sâu nhất so với On-Demand. A/B Reserved/Savings Plans phù hợp workload liên tục, cam kết dài, không tối ưu cho job 3 giờ/ngày chịu ngắt. D Dedicated Host đắt nhất, dùng cho licensing/compliance đặc thù.", "keyword": "Interruptible = Spot Instances"}, {"n": 9, "text": "A company stores private documents in Amazon S3. External auditors who have no AWS account need temporary access to download one specific document for the next 15 minutes only. The solution must follow least privilege. What should a solutions architect recommend?", "options": {"A": "Make the bucket public for 15 minutes and then revert the setting.", "B": "Create an IAM user for each auditor and share the credentials.", "C": "Generate an S3 presigned URL for that object with a 15-minute expiration.", "D": "Copy the document to a public website hosted on EC2."}, "answers": ["C"], "multi": false, "explanation": "Presigned URL cấp quyền tải đúng 1 object, đúng thời hạn 15 phút, không cần AWS account — least privilege hoàn hảo. A public bucket lộ toàn bộ bucket. B tạo IAM user là cấp quyền thừa và phải quản lý credential. D copy ra website công khai làm mất kiểm soát truy cập.", "keyword": "Presigned URL = temporary, object-level access"}, {"n": 10, "text": "A session-based web application stores frequently accessed session data in an RDS database, causing high read latency. The data is key-value, needs sub-millisecond latency, and can expire after 30 minutes. Which service is the BEST fit?", "options": {"A": "Amazon ElastiCache for Redis with TTL configured on session keys.", "B": "Amazon DynamoDB with DynamoDB Accelerator (DAX).", "C": "Amazon EFS.", "D": "Amazon RDS read replica."}, "answers": ["A"], "multi": false, "explanation": "Session dạng key-value, cần latency dưới mili-giây và tự hết hạn sau 30 phút khớp hoàn toàn ElastiCache Redis + TTL. B DAX là cache cho DynamoDB, không phải thay RDS session store kiểu này. C EFS là file system, không phải in-memory cache. D read replica vẫn là database disk-based, latency cao hơn và không có TTL theo key.", "keyword": "ElastiCache Redis, TTL, sub-millisecond"}, {"n": 11, "text": "A web application must remain available if one Availability Zone fails. It runs on EC2 behind an Application Load Balancer. Traffic varies predictably during the day. Which architecture provides high availability with the LEAST operational overhead?", "options": {"A": "One EC2 instance in each of two Regions behind a Route 53 simple record.", "B": "An Auto Scaling group spanning multiple Availability Zones in one Region, behind an Application Load Balancer, with target tracking scaling.", "C": "A single large EC2 instance with an Elastic IP and daily AMI backups.", "D": "EC2 instances in one AZ with Auto Scaling set to a fixed capacity of 1."}, "answers": ["B"], "multi": false, "explanation": "ASG trải nhiều AZ + ALB + target tracking vừa đảm bảo chết 1 AZ vẫn còn instance ở AZ khác, vừa tự co giãn theo tải với ít vận hành. A dùng 2 Region là quá mức và simple record không kiểm tra health. C single instance là single point of failure. D cố định 1 instance trong 1 AZ không có HA.", "keyword": "ASG multi-AZ + ALB = HA"}, {"n": 12, "text": "An EC2 instance in a private subnet must not be reachable from the internet on any port, but it must be able to initiate outbound HTTPS connections. A network engineer is deciding between security groups and network ACLs. Which statement correctly describes the control to use for instance-level, stateful filtering?", "options": {"A": "Use network ACLs, because they are stateful and apply to a single instance.", "B": "Use security groups, because they are stateful, apply at the instance/ENI level, and return traffic is automatically allowed.", "C": "Use network ACLs, because they support allow rules only and are stateful.", "D": "Use security groups, because they are stateless and require explicit inbound and outbound rules for return traffic."}, "answers": ["B"], "multi": false, "explanation": "Security group là stateful, gắn ở ENI/instance, return traffic tự động được cho phép — đúng định nghĩa cần nhớ. A/C sai vì NACL là stateless, áp ở subnet, không phải instance. D đảo ngược tính chất: security group không phải stateless.", "keyword": "SG = stateful, instance level; NACL = stateless, subnet level"}, {"n": 13, "text": "A company uploaded 200 TB of log files to S3 Standard. Analysis shows 95% of the objects are never accessed after 45 days, but the access pattern for the remaining 5% is unknown and unpredictable. Manually classifying objects is not practical. Which S3 storage class will MOST reduce cost without a major performance penalty for the unpredictable objects?", "options": {"A": "S3 Glacier Deep Archive for all objects after 45 days.", "B": "S3 One Zone-IA for all objects after 45 days.", "C": "S3 Intelligent-Tiering with a lifecycle transition after 45 days.", "D": "Keep all objects in S3 Standard-IA."}, "answers": ["C"], "multi": false, "explanation": "Intelligent-Tiering tự động chuyển object giữa các tier dựa trên hành vi truy cập thực tế, hợp khi pattern không dự đoán được và tránh phí retrieval bất ngờ. A Deep Archive retrieval chậm nhiều giờ, rủi ro cho 5% còn truy cập. B One Zone-IA kém bền vững và không tự thích ứng. D Standard-IA tính phí retrieval và vẫn phải đoán pattern.", "keyword": "Unknown access pattern = S3 Intelligent-Tiering"}, {"n": 14, "text": "A DynamoDB table for a product catalog experiences millions of reads per second from a product detail page. The same popular items are read repeatedly and read latency must be in microseconds. Writes are infrequent. Which solution will BEST improve read performance?", "options": {"A": "Enable DynamoDB Streams.", "B": "Add DynamoDB Accelerator (DAX) as a write-through cache in front of the table.", "C": "Increase the provisioned read capacity units to the maximum.", "D": "Create a global secondary index on the product name."}, "answers": ["B"], "multi": false, "explanation": "DAX là cache in-memory tương thích DynamoDB, đưa latency xuống microsecond cho read lặp lại nhiều lần — đúng yêu cầu. A Streams phục vụ xử lý thay đổi/event, không cache read. C tăng RCU chỉ tăng throughput, không giảm latency xuống microsecond. D thêm GSI giúp pattern truy cập khác, không giải quyết hot item lặp lại.", "keyword": "DAX = microsecond DynamoDB cache"}, {"n": 15, "text": "A developer needs temporary access to manage S3 and RDS from an EC2 instance for a production application. Long-term access keys have previously been leaked from a workstation. Which method follows AWS best practices for granting access from EC2?", "options": {"A": "Store an IAM user's access key and secret key in an environment file on the instance.", "B": "Attach an IAM role with an instance profile to the EC2 instance and grant least-privilege permissions in the role policy.", "C": "Use the AWS account root user credentials in the application configuration.", "D": "Embed access keys in the AMI so every new instance has the same credentials."}, "answers": ["B"], "multi": false, "explanation": "IAM role + instance profile cấp credential tạm thời, tự xoay vòng, không lưu long-term key trên máy — best practice chuẩn. A/C/D đều lưu key tĩnh hoặc root credential, rò rỉ là mất toàn quyền và bị cấm trong đề thi lẫn thực tế.", "keyword": "EC2 access = IAM role / instance profile, no access keys"}, {"n": 16, "text": "A company has an RPO of 24 hours and an RTO of 8 hours for a non-critical internal application. It wants the LOWEST-cost disaster recovery strategy that still restores data and infrastructure in another Region when needed. Which strategy should be used?", "options": {"A": "Multi-site active-active across two Regions.", "B": "Warm standby with a scaled-down environment running in the DR Region.", "C": "Pilot light with core data replicated to the DR Region.", "D": "Backup and restore, with backups copied to the DR Region and infrastructure recreated from templates during a disaster."}, "answers": ["D"], "multi": false, "explanation": "RPO 24h / RTO 8h là lỏng nhất, nên backup & restore rẻ nhất vẫn đáp ứng: chỉ sao lưu sang DR Region, khi có sự cố mới dựng lại hạ tầng. A multi-site và B warm standby tốn kém vượt nhu cầu. C pilot light cũng đắt hơn vì phải duy trì replication liên tục cho core data.", "keyword": "Loosest RPO/RTO + lowest cost = Backup & Restore"}, {"n": 17, "text": "A company runs a steady-state, predictable database workload on EC2 instances 24/7 for at least 3 years and will not change instance family or Region. It wants the LARGEST discount for this specific instance configuration. Which purchasing option provides the highest discount?", "options": {"A": "Compute Savings Plans for 1 year, no upfront.", "B": "Standard Reserved Instances for 3 years, all upfront.", "C": "Convertible Reserved Instances for 3 years, partial upfront.", "D": "On-Demand Instances with a volume discount."}, "answers": ["B"], "multi": false, "explanation": "Workload ổn định, cố định family/Region trong 3 năm thì Standard RI 3 năm all upfront cho mức giảm giá cao nhất. A Compute Savings Plans linh hoạt hơn nhưng discount thấp hơn và chỉ 1 năm. C Convertible đổi được family nhưng discount thấp hơn Standard. D On-Demand không có cam kết nên không giảm sâu.", "keyword": "Fixed config + 3yr = Standard RI, max discount"}, {"n": 18, "text": "A company must ensure an S3 bucket containing customer data can never become public, even if a bucket policy or ACL is misconfigured by a developer. The control must apply at the bucket and account level. Which solution meets this requirement?", "options": {"A": "Enable S3 Block Public Access settings on the bucket and at the account level.", "B": "Enable S3 Versioning on the bucket.", "C": "Add a bucket policy that denies s3:GetObject to everyone.", "D": "Enable MFA Delete on the bucket."}, "answers": ["A"], "multi": false, "explanation": "Block Public Access là lớp chặn cứng ở cả bucket và account, ghi đè cả policy/ACL cấu hình sai — đúng yêu cầu \"không bao giờ public\". B Versioning chỉ giúp khôi phục phiên bản. C deny GetObject cho everyone sẽ chặn cả người dùng hợp lệ. D MFA Delete chống xóa nhầm, không chống public access.", "keyword": "S3 Block Public Access overrides policy/ACL"}, {"n": 19, "text": "A company is migrating a high-performance computing workload that requires very low latency and high throughput between EC2 instances for tightly coupled processing. Instances must communicate with each other as directly as possible. Which placement strategy should be used?", "options": {"A": "Spread placement group across multiple Availability Zones.", "B": "Partition placement group.", "C": "Cluster placement group in a single Availability Zone.", "D": "No placement group; launch instances in different Regions."}, "answers": ["C"], "multi": false, "explanation": "Cluster placement group đặt các instance gần nhau trong cùng 1 AZ trên cùng hạ tầng mạng để latency thấp nhất, throughput cao nhất cho HPC tightly coupled. A spread dàn ra để chống lỗi phần cứng, latency cao hơn. B partition cho workload phân tán lớn như Hadoop. D khác Region làm latency tệ nhất.", "keyword": "HPC tightly coupled = Cluster placement group"}, {"n": 20, "text": "An application uses an Application Load Balancer and EC2 instances in two Availability Zones. To survive the loss of an entire AZ without manual intervention and keep serving traffic from the remaining AZ, which design is required?", "options": {"A": "Deploy instances in only one AZ and enable cross-zone load balancing.", "B": "Deploy the ALB and Auto Scaling group across multiple AZs so instances are registered in each AZ.", "C": "Use a Classic Load Balancer with a single instance and an Elastic IP.", "D": "Store session data on a single EBS volume shared by all instances."}, "answers": ["B"], "multi": false, "explanation": "Muốn sống sót khi mất 1 AZ thì cả ALB và ASG/instance phải trải nhiều AZ ngay từ thiết kế. A chỉ ở 1 AZ thì AZ đó chết là sập. C Classic LB + 1 instance là điểm lỗi đơn. D một EBS volume không thể là nơi chứa dữ liệu dùng chung cho HA đa AZ như vậy (và EBS gắn theo AZ).", "keyword": "HA = deploy across multiple AZs"}, {"n": 21, "text": "An application on Lambda needs database credentials that must be automatically rotated every 30 days, with previous versions retained and rotation performed without application downtime. Hardcoding credentials is not allowed. Which service is the BEST choice?", "options": {"A": "AWS Systems Manager Parameter Store with a SecureString parameter.", "B": "AWS Secrets Manager with automatic rotation enabled using a rotation Lambda function.", "C": "Environment variables encrypted with an AWS KMS key in the Lambda configuration.", "D": "An encrypted file stored in Amazon S3."}, "answers": ["B"], "multi": false, "explanation": "Secrets Manager có tính năng automatic rotation tích hợp (qua Lambda), giữ version cũ và xoay vòng không downtime — sinh ra cho database credentials. A Parameter Store SecureString không có rotation tự động tích hợp sẵn cho DB credential như Secrets Manager. C env variable tĩnh, không rotation. D file trên S3 phải tự xây cơ chế rotation.", "keyword": "Auto rotation = Secrets Manager"}, {"n": 22, "text": "A company's primary Region becomes unavailable. Core network and DNS data were continuously replicated to a DR Region, but compute resources are not running there. During a disaster, the team will start the required EC2 instances and scale them up. The RTO is a few hours and cost must stay low during normal operations. Which DR strategy is this?", "options": {"A": "Backup and restore.", "B": "Pilot light.", "C": "Warm standby.", "D": "Multi-site active-active."}, "answers": ["B"], "multi": false, "explanation": "Có replication liên tục cho core (data/network/DNS) nhưng compute chưa chạy, khi sự cố mới bật và scale lên — đó là định nghĩa pilot light. A backup & restore không có replication liên tục của core đang sẵn sàng. C warm standby phải có môi trường đầy đủ chức năng chạy sẵn ở mức nhỏ. D active-active phải đang phục vụ traffic thật.", "keyword": "Pilot light = core replicated, compute off"}, {"n": 23, "text": "An order processing system must preserve the exact order of messages for each customer and ensure each message is processed only once, even with multiple consumers in a group. Throughput per customer group is modest. Which queue type should be used?", "options": {"A": "Amazon SQS standard queue with visibility timeout increased.", "B": "Amazon SQS FIFO queue with a message group ID per customer and deduplication enabled.", "C": "Amazon SNS topic with multiple subscribers.", "D": "Amazon Kinesis Data Streams with one shard."}, "answers": ["B"], "multi": false, "explanation": "Yêu cầu giữ đúng thứ tự + exactly-once theo từng customer chính là FIFO queue + MessageGroupId + deduplication. A standard queue là at-least-once, best-effort ordering, sẽ trùng và sai thứ tự. C SNS là pub/sub, không đảm bảo thứ tự/duy nhất kiểu queue. D Kinesis là stream, cơ chế xử lý khác và không phải exactly-once queue theo group như yêu cầu.", "keyword": "Order + deduplication = SQS FIFO"}, {"n": 24, "text": "A company serves private S3 content through CloudFront. Users must not be able to bypass CloudFront and access the S3 bucket directly via its URL. The bucket must remain private. Which configuration achieves this?", "options": {"A": "Make the bucket public and rely on CloudFront signed URLs.", "B": "Use CloudFront Origin Access Control (OAC) and update the S3 bucket policy to allow access only from the CloudFront distribution.", "C": "Use a bucket policy that allows access from any IP address that CloudFront uses.", "D": "Enable S3 website hosting and set CloudFront to use the website endpoint."}, "answers": ["B"], "multi": false, "explanation": "OAC là cơ chế hiện tại thay OAI: CloudFront ký request tới S3 và bucket policy chỉ cho phép đúng distribution đó, bucket vẫn private, user không bypass được. A public bucket phá yêu cầu private. C dựa trên dải IP CloudFront là không tin cậy/không phải best practice. D website endpoint không dùng được với OAC/private origin đúng cách.", "keyword": "CloudFront OAC, bucket private"}, {"n": 25, "text": "A financial application has an RTO of minutes and an RPO of seconds. A scaled-down but fully functional version of the environment runs continuously in the DR Region and can be scaled up quickly during failover. Which DR strategy is described?", "options": {"A": "Backup and restore.", "B": "Pilot light.", "C": "Warm standby.", "D": "Snapshot copy once per day."}, "answers": ["C"], "multi": false, "explanation": "Môi trường DR đầy đủ chức năng nhưng thu nhỏ, chạy liên tục và scale lên nhanh để đạt RTO phút/RPO giây là warm standby. A backup & restore RTO tính bằng giờ. B pilot light chưa có môi trường đầy đủ chạy sẵn. D snapshot ngày một lần cho RPO tới 24h, sai hẳn.", "keyword": "Warm standby = scaled-down full environment running"}, {"n": 26, "text": "A company commits to a consistent amount of compute usage ($/hour) for 1 year across EC2, Lambda, and Fargate, and wants flexibility to change instance families, sizes, and Regions within EC2 while keeping a high discount. Which option is MOST suitable?", "options": {"A": "Standard Reserved Instances.", "B": "EC2 Instance Savings Plans.", "C": "Compute Savings Plans.", "D": "Spot Instances."}, "answers": ["C"], "multi": false, "explanation": "Compute Savings Plans áp cho EC2 + Lambda + Fargate, cam kết theo $/giờ, linh hoạt family/size/Region nhất trong nhóm Savings Plans. A Standard RI khóa family/Region hơn. B EC2 Instance Savings Plans chỉ cho EC2 và một family/Region. D Spot không có cam kết ổn định cho baseline.", "keyword": "Compute Savings Plans = most flexible, EC2+Lambda+Fargate"}, {"n": 27, "text": "A healthcare company must encrypt EBS volumes and needs to understand how data keys are protected. A solutions architect explains envelope encryption with AWS KMS. Which statement is correct?", "options": {"A": "KMS stores the plaintext data key alongside the data for fast decryption.", "B": "A data key encrypts the data, and the KMS key encrypts the data key; only the encrypted data key is stored with the data.", "C": "The KMS key itself is sent to EC2 and used directly to encrypt every disk block.", "D": "Envelope encryption requires customers to manage master keys entirely outside AWS."}, "answers": ["B"], "multi": false, "explanation": "Envelope encryption: data key mã hóa dữ liệu, KMS key mã hóa data key, chỉ bản encrypted data key được lưu cùng dữ liệu; plaintext data key chỉ tồn tại trong bộ nhớ khi dùng. A sai vì lưu plaintext key sẽ vô hiệu mã hóa. C KMS key không rời HSM để mã hóa từng block. D key vẫn được quản lý trong AWS KMS.", "keyword": "Envelope encryption = encrypted data key stored with data"}, {"n": 28, "text": "An application needs a shared file system that multiple EC2 instances in multiple Availability Zones can mount concurrently using the NFS protocol, with data automatically replicated across AZs. Which storage service meets this requirement?", "options": {"A": "Amazon EBS with Multi-Attach.", "B": "Instance store volumes.", "C": "Amazon EFS.", "D": "Amazon S3 mounted with a third-party tool."}, "answers": ["C"], "multi": false, "explanation": "EFS là NFS shared file system, mount đồng thời từ nhiều instance/nhiều AZ và tự replicate trong Region. A EBS chủ yếu gắn 1 AZ/instance (Multi-Attach rất giới hạn, cùng AZ). B instance store là tạm, mất khi instance dừng/chết. D S3 là object storage, không phải file system NFS thực thụ.", "keyword": "Shared NFS multi-AZ = EFS"}, {"n": 29, "text": "A company must protect RDS database data against accidental deletion and be able to restore to any point in time within the last 7 days. It also needs automated backups with minimal manual work. Which feature should be enabled?", "options": {"A": "Create a read replica and rely on it as a backup.", "B": "Enable automated backups with a 7-day retention period to use point-in-time recovery.", "C": "Export the database manually to S3 once per month.", "D": "Enable Multi-AZ and assume no backups are needed."}, "answers": ["B"], "multi": false, "explanation": "Automated backups + retention 7 ngày cho phép point-in-time recovery tới bất kỳ giây nào trong 7 ngày và chống mất dữ liệu khi xóa nhầm tốt nhất với ít vận hành. A read replica không phải backup và lỗi xóa sẽ replicate sang. C export tháng một lần không đạt PITR 7 ngày. D Multi-AZ chống lỗi hạ tầng, không chống xóa nhầm và không thay backup.", "keyword": "Automated backup + PITR, Multi-AZ ≠ backup"}, {"n": 30, "text": "An organization has separate OUs for Production and Development. Developers in Development must be prevented from launching large, expensive instance types, even if their IAM policies allow it. The control must apply to the entire Development OU. Which solution should be used?", "options": {"A": "Add a condition to each developer's IAM policy in each account.", "B": "Attach an SCP to the Development OU that denies ec2:RunInstances when the requested instance type is not in an approved list.", "C": "Use a VPC endpoint policy to block large instance launches.", "D": "Set a billing budget alert for the Development accounts."}, "answers": ["B"], "multi": false, "explanation": "SCP gắn ở OU áp cho mọi account trong OU và chặn cả khi IAM policy cho phép — đúng cơ chế \"trần quyền\" của Organizations. A phải sửa từng policy, dễ sót và bị admin sửa lại. C VPC endpoint policy chỉ kiểm soát traffic qua endpoint, không kiểm soát RunInstances. D budget chỉ cảnh báo chi phí, không chặn hành động.", "keyword": "SCP at OU = guardrail for all accounts"}, {"n": 31, "text": "A data analytics team stores access logs in S3. About 80% of objects are accessed once and then never again, but the team cannot predict which objects will be accessed again. After 30 days, retrieval can tolerate standard access latency but data must stay highly durable across multiple AZs. Which class BEST balances cost and risk?", "options": {"A": "S3 One Zone-IA.", "B": "S3 Intelligent-Tiering.", "C": "S3 Glacier Deep Archive.", "D": "S3 Standard, with no lifecycle policy."}, "answers": ["B"], "multi": false, "explanation": "Intelligent-Tiering tự học pattern từng object, giữ durability đa AZ và không bắt đội phải đoán object nào sẽ được đọc lại, cân bằng tốt nhất cho log khó đoán. A One Zone-IA rẻ hơn nhưng rủi ro mất AZ và không tự thích ứng. C Deep Archive retrieval chậm, không hợp yêu cầu latency tiêu chuẩn. D giữ Standard là đắt không cần thiết.", "keyword": "Intelligent-Tiering = unknown pattern + multi-AZ durability"}, {"n": 32, "text": "Users in multiple continents experience high latency and frequent TCP connection issues when connecting to a single-Region application on EC2. The application uses a static public IP requirement for firewall allowlisting by partners. Which service will improve global performance and provide static anycast IPs?", "options": {"A": "Amazon CloudFront with a custom origin.", "B": "AWS Global Accelerator with an Application Load Balancer endpoint.", "C": "Route 53 geolocation routing.", "D": "S3 Transfer Acceleration."}, "answers": ["B"], "multi": false, "explanation": "Global Accelerator dùng mạng AWS toàn cầu + anycast static IP, cải thiện latency/độ ổn định TCP cho ứng dụng đa châu lục và đáp ứng nhu cầu IP tĩnh cho allowlist. A CloudFront mạnh cho cache nội dung HTTP, không phải giải pháp IP tĩnh anycast cho app tổng quát. C geolocation chỉ chọn endpoint theo vị trí. D Transfer Acceleration chỉ cho upload S3.", "keyword": "Global Accelerator = static anycast IP, global performance"}, {"n": 33, "text": "A company uses Route 53 for a public website backed by an ALB. If the ALB endpoint becomes unhealthy, Route 53 must stop returning its IP address to clients. Which Route 53 feature must be configured and associated with the DNS record?", "options": {"A": "A Route 53 health check associated with the record, with DNS failover/evaluate target health enabled.", "B": "A weighted routing policy with equal weights.", "C": "A geoproximity routing policy.", "D": "DNSSEC signing for the hosted zone."}, "answers": ["A"], "multi": false, "explanation": "Health check (hoặc evaluate target health với ALB) là điều kiện để Route 53 ngừng trả về endpoint unhealthy. B weighted chỉ chia tỉ lệ traffic, không tự loại endpoint chết. C geoproximity định tuyến theo khoảng cách. D DNSSEC chống giả mạo DNS, không liên quan health.", "keyword": "Route 53 health check = stop returning unhealthy endpoint"}, {"n": 34, "text": "EC2 instances in private subnets need frequent, high-volume access to Amazon S3 and Amazon DynamoDB without traffic traversing the internet or a NAT gateway. The solution must be at no additional hourly charge for the endpoint itself. Which solution meets this requirement?", "options": {"A": "Create Interface VPC endpoints (AWS PrivateLink) for S3 and DynamoDB.", "B": "Create Gateway VPC endpoints for S3 and DynamoDB and add them to the private subnet route tables.", "C": "Place a NAT gateway in each private subnet.", "D": "Create an internet gateway and restrict access with security groups."}, "answers": ["B"], "multi": false, "explanation": "S3 và DynamoDB là 2 dịch vụ duy nhất hỗ trợ Gateway Endpoint — miễn phí, đi qua route table, không qua internet/NAT. A Interface Endpoint tính phí theo giờ + GB và không cần thiết cho 2 dịch vụ này. C NAT tốn phí và vẫn đi đường vòng. D internet gateway phá yêu cầu private.", "keyword": "Gateway Endpoint FREE for S3 + DynamoDB only"}, {"n": 35, "text": "A company runs a CPU-intensive, non-critical workload on x86 EC2 instances and wants to reduce cost without changing application code significantly. The application is built for ARM and has been tested successfully. Which action provides a cost-performance benefit with minimal risk after testing?", "options": {"A": "Migrate the workload to AWS Graviton-based instances.", "B": "Move the workload to Dedicated Hosts.", "C": "Increase the instance size in the same x86 family.", "D": "Convert all instances to Standard Reserved Instances without testing."}, "answers": ["A"], "multi": false, "explanation": "Graviton (ARM) thường cho price-performance tốt hơn x86 đáng kể, và bài đã nêu app tương thích ARM + đã test thành công nên rủi ro thấp. B Dedicated Host tăng chi phí. C tăng size x86 chỉ tốn thêm tiền. D mua RI 3 năm khi chưa test là khóa chi phí sai hướng.", "keyword": "Graviton = better price-performance"}, {"n": 36, "text": "A database application requires the lowest possible latency block storage directly attached to a single EC2 instance, with very high IOPS and durability handled by application-level replication across instances. Temporary data loss on instance failure is acceptable. Which storage is BEST?", "options": {"A": "Amazon EFS.", "B": "EC2 instance store (NVMe SSD).", "C": "Amazon EBS General Purpose SSD (gp3).", "D": "Amazon S3."}, "answers": ["B"], "multi": false, "explanation": "Instance store NVMe gắn trực tiếp vật lý cho latency thấp nhất và IOPS rất cao, đổi lại dữ liệu mất khi instance chết — đề đã chấp nhận vì có replication ở tầng app. A EFS là network file system, latency cao hơn. C gp3 bền nhưng qua network, không thấp bằng local NVMe. D S3 là object storage, không phải block storage.", "keyword": "Lowest latency block = instance store (ephemeral)"}, {"n": 37, "text": "A regulated company must retain financial records in S3 for 7 years. Records must be impossible to delete or overwrite during the retention period, even by the account root user. Which feature must be used?", "options": {"A": "S3 Versioning with MFA Delete.", "B": "S3 Object Lock in compliance mode with a 7-year retention period.", "C": "A bucket policy that denies s3:DeleteObject.", "D": "S3 Glacier Vault Lock only, without Object Lock."}, "answers": ["B"], "multi": false, "explanation": "Object Lock compliance mode khóa object đúng nghĩa WORM: không ai, kể cả root, xóa/ghi đè được trước khi hết retention. A MFA Delete vẫn xóa được nếu có MFA + quyền. C bucket policy có thể bị sửa bởi người có quyền quản trị policy. D Vault Lock là cho Glacier vault, không thay Object Lock cho S3 object retention kiểu này.", "keyword": "WORM / immutable = S3 Object Lock compliance mode"}, {"n": 38, "text": "A company runs Amazon Aurora PostgreSQL in one Region and needs a disaster recovery solution in a second Region with an RPO of typically less than 1 second of lag and an RTO of less than 1 minute for a managed failover, while the secondary must support read queries during normal operations. (Select TWO)", "options": {"A": "Use Aurora Global Database with a secondary Region cluster.", "B": "The secondary cluster in Aurora Global Database can serve read queries with its own reader endpoint.", "C": "Restore daily snapshots in the second Region when a disaster occurs.", "D": "Use DMS to copy data once per day to the second Region.", "E": "Rely on Aurora Multi-AZ replicas in the same Region for cross-Region DR."}, "answers": ["A", "B"], "multi": true, "explanation": "Aurora Global Database cho replication liên Region với lag thường <1 giây, failover có quản lý dưới 1 phút, và secondary cluster có reader endpoint để đọc trong lúc bình thường — khớp cả RPO/RTO lẫn yêu cầu đọc. C restore snapshot cho RTO hàng giờ. D DMS copy ngày một lần cho RPO 24h. E Multi-AZ chỉ trong cùng Region, không phải DR liên Region.", "keyword": "Aurora Global Database = cross-Region, <1s lag"}, {"n": 39, "text": "Several EC2 instances are consistently running at 15% CPU and 20% memory utilization. A finance team asks for a data-driven recommendation to rightsize instances and reduce waste. Which AWS tool provides resource-specific rightsizing recommendations based on utilization history?", "options": {"A": "AWS Trusted Advisor basic checks only.", "B": "AWS Compute Optimizer.", "C": "Amazon CloudWatch billing alarms.", "D": "AWS Cost Explorer forecasts only."}, "answers": ["B"], "multi": false, "explanation": "Compute Optimizer phân tích lịch sử utilization (CloudWatch) và đưa khuyến nghị rightsize cụ thể theo resource. A Trusted Advisor chỉ có một số check cơ bản, không thay Compute Optimizer cho rightsizing chuyên sâu. C billing alarm chỉ báo tiền. D Cost Explorer forecast dự báo chi phí tổng, không khuyến nghị đổi size từng instance.", "keyword": "Rightsizing recommendations = Compute Optimizer"}, {"n": 40, "text": "A security audit finds that developers have IAM policies granting full S3 access to all buckets. The company wants to identify unused permissions and generate a least-privilege policy based on actual access history. Which tool should be used?", "options": {"A": "AWS IAM Access Analyzer policy generation based on CloudTrail activity.", "B": "Amazon Macie.", "C": "AWS Trusted Advisor security checks.", "D": "Amazon Inspector."}, "answers": ["A"], "multi": false, "explanation": "IAM Access Analyzer có thể generate policy từ hoạt động CloudTrail thực tế và phân tích unused access, giúp thu hẹp quyền đúng least privilege. B Macie tìm dữ liệu nhạy cảm (PII) trong S3. C Trusted Advisor chỉ check bề mặt. D Inspector quét lỗ hổng trên EC2/container/lambda.", "keyword": "Access Analyzer = generate least-privilege policy from CloudTrail"}, {"n": 41, "text": "An application must ingest a continuous stream of clickstream events at 500 MB/s, retain the data for 24 hours for replay, and allow multiple independent consumers to process the same data in order per partition key. Which service is BEST suited?", "options": {"A": "Amazon SQS standard queue.", "B": "Amazon Kinesis Data Streams with sufficient shards and enhanced fan-out or separate consumers.", "C": "Amazon SNS.", "D": "Amazon EventBridge with a schedule rule."}, "answers": ["B"], "multi": false, "explanation": "Clickstream tốc độ cao, cần giữ thứ tự theo partition key, replay trong 24h và nhiều consumer độc lập là đúng thiết kế của Kinesis Data Streams. A SQS không giữ stream để replay cho nhiều consumer như vậy và throughput/ordering khác bản chất. C SNS là push pub/sub, không lưu stream để replay. D EventBridge cho event routing, không phải high-throughput streaming.", "keyword": "Streaming + replay + multiple consumers = Kinesis Data Streams"}, {"n": 42, "text": "A company stores critical objects in S3 in us-east-1 and must keep a copy in eu-west-1 for disaster recovery. New objects must be replicated automatically, with versioning enabled on both buckets. Which feature should be configured?", "options": {"A": "S3 Cross-Region Replication between versioning-enabled buckets.", "B": "S3 Lifecycle policy with a transition to another Region.", "C": "AWS DataSync run manually once per month.", "D": "S3 Batch Copy run on demand."}, "answers": ["A"], "multi": false, "explanation": "S3 Cross-Region Replication tự động replicate object mới (và version) sang bucket ở Region khác, bắt buộc versioning ở cả hai bucket. B Lifecycle chỉ chuyển storage class trong cùng bucket, không đổi Region. C DataSync thủ công tháng một lần không tự động/liên tục. D Batch Copy là tác vụ on-demand, không phải replication liên tục.", "keyword": "CRR requires versioning on source + destination"}, {"n": 43, "text": "A company must ensure all data in transit between clients and its Application Load Balancer uses TLS, with certificates automatically renewed and no manual certificate management. Which service should be used for the certificates?", "options": {"A": "Store a self-signed certificate on each EC2 instance.", "B": "Use AWS Certificate Manager (ACM) certificates on the ALB with automatic renewal.", "C": "Use an S3 bucket to host the certificate files.", "D": "Use AWS KMS to generate TLS certificates for the ALB."}, "answers": ["B"], "multi": false, "explanation": "ACM cấp và tự động gia hạn chứng chỉ TLS dùng trực tiếp trên ALB/CloudFront, loại bỏ vận hành thủ công. A self-signed không được trình duyệt tin cậy và phải tự quản lý. C S3 không phải nơi quản lý cert cho ALB. D KMS quản lý encryption key, không cấp TLS certificate cho ALB.", "keyword": "ACM = free TLS cert + auto renewal for ALB/CloudFront"}, {"n": 44, "text": "A company runs a nightly ETL job that queries only a small subset of columns and rows from 10 TB of CSV data stored in S3. Running a full cluster for this query is expensive. Which approach is MOST cost-effective for ad hoc queries directly on S3 data?", "options": {"A": "Load all data into Amazon Redshift every night before querying.", "B": "Use Amazon Athena with partitioned data and a columnar format such as Parquet to reduce scanned data.", "C": "Copy data to EBS volumes and query with EC2 instances.", "D": "Use Amazon RDS for MySQL to import the CSV files."}, "answers": ["B"], "multi": false, "explanation": "Athena query trực tiếp trên S3 theo kiểu serverless trả tiền theo dữ liệu quét; dùng Parquet + partitioning giảm mạnh dữ liệu quét và chi phí cho query ad hoc chỉ lấy ít cột/dòng. A Redshift phải duy trì cluster và nạp dữ liệu mỗi đêm, đắt cho ad hoc. C EC2/EBS tự vận hành tốn kém. D import 10 TB vào RDS là sai công cụ.", "keyword": "Athena + Parquet + partition = pay per scan"}, {"n": 45, "text": "A product recommendation engine needs a fast in-memory data store that supports sorted sets, leaderboards, and geospatial queries, with persistence and automatic failover. Which ElastiCache engine is the BEST fit?", "options": {"A": "ElastiCache for Memcached.", "B": "ElastiCache for Redis (Valkey/Redis OSS) with Multi-AZ automatic failover.", "C": "DynamoDB DAX.", "D": "Amazon RDS read replica."}, "answers": ["B"], "multi": false, "explanation": "Redis hỗ trợ sorted set, leaderboard, geospatial, persistence và Multi-AZ failover — Memcached không có các data structure và persistence đó. A Memcached chỉ cache đơn giản, đa luồng, không persistence/failover kiểu này. C DAX chỉ cache cho DynamoDB. D read replica là database quan hệ, không phải in-memory store cho leaderboard.", "keyword": "Sorted sets / leaderboard = ElastiCache for Redis"}, {"n": 46, "text": "A stateless containerized application runs on Amazon ECS with Fargate. It must survive an AZ failure automatically and scale based on request count without managing EC2 instances. Which configuration achieves this?", "options": {"A": "Deploy the ECS service in one AZ with a desired count of 1.", "B": "Deploy the ECS service across multiple AZs in a VPC, behind an ALB, with Application Auto Scaling.", "C": "Run containers on a single EC2 instance with ECS.", "D": "Use ECS with a capacity provider of one Dedicated Host."}, "answers": ["B"], "multi": false, "explanation": "ECS service trải nhiều AZ + ALB + Application Auto Scaling trên Fargate cho HA theo AZ và scale không cần quản lý EC2. A 1 AZ / desired 1 là điểm lỗi đơn. C 1 EC2 instance cũng vậy. D Dedicated Host đi ngược mục tiêu không quản lý hạ tầng.", "keyword": "Fargate multi-AZ + ALB = serverless HA containers"}, {"n": 47, "text": "A public web application must be protected against common web exploits such as SQL injection and cross-site scripting at the application layer, and against large-scale DDoS attacks at the network edge. (Select TWO)", "options": {"A": "Attach AWS WAF to the Application Load Balancer or CloudFront distribution with managed rule groups for SQL injection and XSS.", "B": "Enable AWS Shield Advanced or rely on AWS Shield Standard for DDoS protection at no additional configuration for supported resources.", "C": "Use security groups to inspect HTTP request bodies for SQL injection patterns.", "D": "Use S3 Block Public Access to filter web exploits.", "E": "Use Route 53 health checks to block SQL injection."}, "answers": ["A", "B"], "multi": true, "explanation": "WAF lọc ở Layer 7 (SQLi, XSS) khi gắn vào ALB/CloudFront, còn Shield (Standard mặc định / Advanced nâng cao) lo DDoS ở tầng mạng/transport — hai lớp bổ sung nhau. C security group không đọc được HTTP body. D Block Public Access là của S3, không lọc exploit. E health check chỉ kiểm tra sức khỏe endpoint.", "keyword": "WAF = L7 exploits, Shield = DDoS"}, {"n": 48, "text": "A new application has unpredictable DynamoDB traffic with sharp, infrequent spikes. The team wants to avoid capacity planning and throttling, and is willing to pay per request rather than provision capacity that sits idle. Which capacity mode is MOST cost-effective for this pattern?", "options": {"A": "Provisioned capacity with a fixed high RCU/WCU set for peak load.", "B": "Provisioned capacity with Auto Scaling set to a minimum of peak load.", "C": "DynamoDB on-demand capacity mode.", "D": "Use RDS instead to avoid DynamoDB capacity settings."}, "answers": ["C"], "multi": false, "explanation": "Traffic khó đoán, spike thưa và bất ngờ thì on-demand tính theo request, không cần dự báo capacity và không throttling do thiếu RCU/WCU, rẻ hơn việc provision cho peak rồi để idle. A/B provision cho peak gây lãng phí lớn phần lớn thời gian. D đổi sang RDS là thay đổi kiến trúc không cần thiết.", "keyword": "Unpredictable spikes = DynamoDB on-demand"}, {"n": 49, "text": "Many Lambda functions and EC2 applications open thousands of short-lived connections to an RDS database, causing \"too many connections\" errors and uneven load. The company wants connection pooling and reduced failover time without changing application code significantly. Which service should be placed in front of RDS?", "options": {"A": "Amazon RDS Proxy.", "B": "Amazon ElastiCache for Memcached.", "C": "An Application Load Balancer in front of the database.", "D": "Amazon Route 53 weighted records for the DB endpoint."}, "answers": ["A"], "multi": false, "explanation": "RDS Proxy pool và tái sử dụng connection, giảm lỗi too many connections và cải thiện failover (giảm thời gian chuyển đổi) mà app gần như không phải sửa nhiều. B ElastiCache là cache dữ liệu, không pool DB connection. C ALB không proxy được giao thức database RDS như Proxy. D Route 53 không quản lý connection.", "keyword": "RDS Proxy = connection pooling"}, {"n": 50, "text": "A company manages hundreds of accounts and needs a centralized backup solution that can enforce backup policies across accounts and Regions, with reporting and no per-server agent management for AWS resources such as EBS, RDS, and DynamoDB. Which service meets this requirement?", "options": {"A": "Manually create snapshots in each account.", "B": "AWS Backup with backup plans and an organization-wide backup policy.", "C": "S3 Lifecycle policies for all resources.", "D": "AWS Systems Manager Run Command to copy data nightly."}, "answers": ["B"], "multi": false, "explanation": "AWS Backup là dịch vụ tập trung, tạo backup plan/policy áp dụng xuyên account/Region qua Organizations, có báo cáo compliance và không cần agent cho các resource AWS được hỗ trợ. A thủ công từng account không scale. C Lifecycle của S3 không backup được EBS/RDS/DynamoDB. D Run Command tự chế, giòn và tốn vận hành.", "keyword": "Centralized backup = AWS Backup + backup policy"}, {"n": 51, "text": "Employees of a company need single sign-on access to multiple AWS accounts in AWS Organizations using their existing corporate identity provider credentials, without creating separate IAM users in each account. Which solution should be implemented?", "options": {"A": "Create an IAM user for each employee in every AWS account.", "B": "Use IAM Identity Center integrated with the external identity provider and assign permission sets to accounts.", "C": "Share one IAM user and password among all employees.", "D": "Store corporate passwords in Secrets Manager."}, "answers": ["B"], "multi": false, "explanation": "IAM Identity Center (SSO) liên kết IdP ngoài, cấp permission set tạm thời theo account — nhân viên dùng 1 danh tính công ty cho nhiều account, không tạo IAM user lẻ. A tạo user khắp nơi gây phình quản lý và key tĩnh. C dùng chung tài khoản vi phạm truy vết. D lưu password công ty vào Secrets Manager là sai mục đích và nguy hiểm.", "keyword": "SSO multi-account = IAM Identity Center + permission sets"}, {"n": 52, "text": "An Auto Scaling group runs a fault-tolerant workload that can mix purchasing options. The company needs a guaranteed baseline of capacity that is always available, plus additional low-cost capacity that can be interrupted for the flexible portion. Which configuration is BEST?", "options": {"A": "Use only Spot Instances for the entire group.", "B": "Use a mixed instances policy with On-Demand Instances for the baseline capacity and Spot Instances for capacity above the baseline.", "C": "Use only Dedicated Hosts for all capacity.", "D": "Use a fixed number of On-Demand Instances with no Auto Scaling."}, "answers": ["B"], "multi": false, "explanation": "Mixed instances policy cho phép đặt baseline On-Demand đảm bảo luôn có capacity, phần vượt baseline dùng Spot giá rẻ và chịu ngắt được — cân bằng cost/độ tin cậy chuẩn đề thi. A toàn Spot rủi ro mất toàn bộ capacity. C Dedicated Host đắt vô ích. D fixed On-Demand không có lợi ích co giãn/Spot.", "keyword": "Mixed ASG = On-Demand baseline + Spot above baseline"}, {"n": 53, "text": "A query workload on large datasets in S3 needs interactive SQL analysis by many analysts. Data is structured, queries are ad hoc, and the team does not want to manage servers or load data into a database first. Which service is BEST?", "options": {"A": "Amazon Athena.", "B": "Amazon RDS for PostgreSQL.", "C": "Amazon EMR with a long-running cluster kept idle 24/7.", "D": "Amazon EC2 instances with a self-managed database."}, "answers": ["A"], "multi": false, "explanation": "Athena là serverless SQL trực tiếp trên S3, không phải quản lý server hay load dữ liệu trước, hợp nhất cho analyst query ad hoc. B RDS phải nạp dữ liệu và giới hạn scale. C EMR cluster chạy idle 24/7 tốn tiền và vận hành. D tự quản DB trên EC2 là nặng nhất.", "keyword": "Serverless SQL on S3 = Athena"}, {"n": 54, "text": "An application deployed with Elastic Beanstalk needs a deployment that minimizes downtime and allows immediate rollback if the new version fails health checks, by swapping environment URLs. Which deployment approach in Elastic Beanstalk provides this?", "options": {"A": "All-at-once deployment to the existing environment.", "B": "Blue/green deployment by creating a new environment and swapping CNAMEs after validation.", "C": "Delete the old environment before deploying the new version.", "D": "In-place deployment without health checks."}, "answers": ["B"], "multi": false, "explanation": "Blue/green trong Beanstalk tạo môi trường mới, kiểm tra khỏe rồi swap CNAME — downtime tối thiểu và rollback chỉ là swap lại URL. A all-at-once gây downtime và khó rollback. C xóa môi trường cũ trước là mất đường lui. D in-place không health check rủi ro phát hành bản lỗi.", "keyword": "Beanstalk blue/green = swap CNAME, fast rollback"}, {"n": 55, "text": "EC2 instances in private subnets need to call AWS APIs such as SSM and Secrets Manager, but the VPC must have no internet gateway and no NAT gateway. Outbound internet access must be completely blocked. Which solution allows access to those AWS services privately?", "options": {"A": "Add an internet gateway and allow 0.0.0.0/0 in the route table.", "B": "Create Interface VPC endpoints (AWS PrivateLink) for the required services and associate them with the private subnets.", "C": "Use a public subnet for the instances instead.", "D": "Peer the VPC with a VPC that has internet access."}, "answers": ["B"], "multi": false, "explanation": "Interface Endpoint (PrivateLink) tạo ENI có IP private trong subnet cho từng dịch vụ AWS, traffic đi hoàn toàn trong mạng AWS private, không cần IGW/NAT. A/C đưa instance ra internet, phá yêu cầu. D VPC peering sang VPC có internet vẫn là đường ra internet gián tiếp và không phải cách truy cập AWS API private chuẩn.", "keyword": "No IGW/NAT + AWS APIs = Interface VPC Endpoint"}, {"n": 56, "text": "A company stores backup data that is rarely accessed and can be recreated from other sources if an Availability Zone is lost. It wants the lowest-cost S3 storage class that still provides 99.5% availability for infrequently accessed data stored in a single AZ. Which class should be chosen, accepting the AZ-loss risk?", "options": {"A": "S3 Standard.", "B": "S3 Standard-IA.", "C": "S3 One Zone-IA.", "D": "S3 Intelligent-Tiering."}, "answers": ["C"], "multi": false, "explanation": "One Zone-IA lưu dữ liệu ở 1 AZ nên rẻ nhất trong nhóm IA, availability 99.5%, chỉ hợp dữ liệu tái tạo được và chấp nhận mất khi AZ hỏng — đề đã nêu rõ 2 điều kiện đó. A Standard đắt và đa AZ không cần thiết. B Standard-IA đa AZ nên đắt hơn One Zone. D Intelligent-Tiering cũng đa AZ và có phí monitoring.", "keyword": "Cheapest IA, recreatable = S3 One Zone-IA"}, {"n": 57, "text": "A database workload requires sustained 80,000 IOPS, low single-digit millisecond latency, and up to 64 TB of block storage per volume that persists independently of a single instance's lifetime and can be reattached after an instance failure. Which EBS volume type is BEST?", "options": {"A": "General Purpose SSD (gp3) with default settings.", "B": "Throughput Optimized HDD (st1).", "C": "Provisioned IOPS SSD (io2 / io2 Block Express).", "D": "Cold HDD (sc1)."}, "answers": ["C"], "multi": false, "explanation": "io2 / io2 Block Express là dòng Provisioned IOPS cao cấp, đạt tới hàng chục nghìn–trăm nghìn IOPS, dung lượng lớn và persistent độc lập với instance. A gp3 mặc định IOPS thấp hơn nhiều và phải tune mới tăng, không phải lựa chọn tốt nhất cho 80k bền vững kiểu này. B/D HDD (st1/sc1) mạnh về throughput/giá, latency và IOPS kém.", "keyword": "Highest IOPS EBS = io2"}, {"n": 58, "text": "A company needs synchronous replication of database writes so that a standby copy always has the same data as the primary at failover, with no data loss, within a single Region. Asynchronous cross-Region replication alone is not acceptable as the primary HA mechanism. Which concept describes the correct in-Region design?", "options": {"A": "Use read replicas with asynchronous replication as the HA standby.", "B": "Use Multi-AZ deployment, which uses synchronous replication to a standby in another AZ.", "C": "Copy snapshots to another Region every hour.", "D": "Use S3 Cross-Region Replication for the database files."}, "answers": ["B"], "multi": false, "explanation": "Trong cùng Region, cơ chế HA không mất dữ liệu là Multi-AZ với synchronous replication sang standby khác AZ. A read replica là asynchronous nên có thể lag và mất dữ liệu khi failover ép buộc. C snapshot theo giờ cho RPO 1 giờ. D CRR của S3 không liên quan replication của database engine.", "keyword": "Synchronous = Multi-AZ, Asynchronous = Read Replica"}, {"n": 59, "text": "A new AWS account's root user must be secured immediately after creation. The company wants to prevent root user compromise and ensure day-to-day work never uses root. Which action is MOST important to do first?", "options": {"A": "Create an IAM user with full administrator access and share it among the team.", "B": "Enable MFA on the root user, set a strong password, and delete/create no root access keys; use IAM roles/users for daily work.", "C": "Enable S3 Versioning in the account.", "D": "Create a billing alarm for the root user."}, "answers": ["B"], "multi": false, "explanation": "Root là quyền tối cao không giới hạn: phải bật MFA, đặt mật khẩu mạnh, không dùng access key của root và không dùng root cho việc hằng ngày. A tạo admin user dùng chung vẫn là credential chia sẻ nguy hiểm. C/D là việc phụ, không bảo vệ được tài khoản nếu root bị chiếm.", "keyword": "Secure root first = MFA + no root access keys"}, {"n": 60, "text": "A company wants to lower EC2 cost for instances that are stopped at night. Developers forget to stop test instances, which then run idle for days. Which approach will MOST reduce cost with the LEAST ongoing manual effort for these non-production instances?", "options": {"A": "Require developers to remember to stop instances manually every day.", "B": "Use AWS Instance Scheduler / EventBridge Scheduler with Lambda or Systems Manager to automatically stop instances on a schedule, and use hibernation or stop (not terminate) where appropriate.", "C": "Convert all test instances to 3-year Reserved Instances.", "D": "Increase the instance size so jobs finish faster."}, "answers": ["B"], "multi": false, "explanation": "Lên lịch tự động stop bằng Instance Scheduler/EventBridge + Lambda/Systems Manager loại bỏ lỗi quên của con người, instance stopped chỉ tốn tiền EBS nên giảm chi phí rõ rệt cho môi trường test. A phụ thuộc trí nhớ, đã chứng minh không hiệu quả. C RI 3 năm khóa tiền cho máy chạy không liên tục. D tăng size không giải quyết idle quên tắt.", "keyword": "Auto stop schedule = stop non-prod when idle"}, {"n": 61, "text": "Which TWO practices follow IAM least-privilege and security best practices for a production AWS account? (Select TWO)", "options": {"A": "Grant permissions through IAM groups/roles with policies scoped to only the actions and resources needed for the job.", "B": "Require MFA for human users signing in to the AWS Management Console.", "C": "Share long-term access keys among team members to simplify rotation.", "D": "Use the root user for daily application deployment tasks.", "E": "Grant AdministratorAccess to all developers to avoid permission errors."}, "answers": ["A", "B"], "multi": true, "explanation": "Least privilege (chỉ cấp đúng action/resource qua group/role) và MFA cho human console access là 2 best practice cốt lõi. C chia sẻ access key phá truy vết và rotation. D dùng root hằng ngày bị cấm theo best practice. E cấp AdministratorAccess cho mọi người là trái ngược least privilege.", "keyword": "Least privilege + MFA for humans"}, {"n": 62, "text": "A company wants a highly available architecture for a three-tier web application in a single Region. Which TWO design choices are required for high availability across Availability Zones? (Select TWO)", "options": {"A": "Deploy the Application Load Balancer and application instances across at least two Availability Zones.", "B": "Use Amazon RDS Multi-AZ with a synchronous standby in a different Availability Zone.", "C": "Store all application data on a single EBS volume in one AZ.", "D": "Place all EC2 instances in a single AZ to reduce latency.", "E": "Use a single NAT gateway in one AZ with no redundancy plan and consider the design fully HA."}, "answers": ["A", "B"], "multi": true, "explanation": "HA trong 1 Region = loại bỏ điểm lỗi đơn theo AZ: LB + app trải ≥2 AZ và RDS Multi-AZ synchronous standby ở AZ khác. C một EBS volume ở 1 AZ là single point of failure (EBS gắn theo AZ). D dồn hết vào 1 AZ thì mất AZ là sập. E một NAT gateway duy nhất cũng không phải thiết kế HA đầy đủ, dù NAT không nằm trong 2 đáp án đúng yêu cầu.", "keyword": "HA = multi-AZ for compute + Multi-AZ for DB"}, {"n": 63, "text": "Which TWO actions will MOST improve performance for a read-heavy application serving users worldwide from data stored in S3 and RDS? (Select TWO)", "options": {"A": "Use Amazon CloudFront to cache static S3 content at edge locations close to users.", "B": "Create RDS read replicas and route read traffic to them.", "C": "Route all reads through a single small EC2 instance in one AZ.", "D": "Disable caching to ensure every request reaches the origin.", "E": "Increase the RDS primary instance's workload by adding reporting queries to it."}, "answers": ["A", "B"], "multi": true, "explanation": "CloudFront đưa nội dung tĩnh lại gần user toàn cầu và giảm tải origin, còn read replica tách tải đọc khỏi primary RDS — cả hai trực tiếp cải thiện read performance. C dồn read qua 1 instance nhỏ tạo nút thắt. D tắt cache làm mọi request về origin, chậm hơn. E dồn thêm reporting lên primary làm primary quá tải hơn.", "keyword": "Global read perf = CloudFront + Read Replica"}, {"n": 64, "text": "A company wants to reduce its AWS bill without reducing reliability for production workloads. Which TWO actions are generally cost-effective and low risk? (Select TWO)", "options": {"A": "Use S3 Lifecycle policies to transition older, infrequently accessed objects to cheaper storage classes.", "B": "Purchase Savings Plans or Reserved Instances for steady-state, predictable baseline usage after analyzing usage in Cost Explorer.", "C": "Delete all backups and snapshots immediately after creation.", "D": "Run production databases on Spot Instances as the only copy.", "E": "Keep idle, unattached EBS volumes and unused Elastic IPs indefinitely."}, "answers": ["A", "B"], "multi": true, "explanation": "Lifecycle chuyển object cũ sang class rẻ hơn và mua Savings Plans/RI cho baseline ổn định (sau khi phân tích Cost Explorer) là 2 cách giảm tiền kinh điển, ít rủi ro. C xóa backup phá khả năng khôi phục. D chạy DB production duy nhất trên Spot có thể bị thu hồi bất cứ lúc nào. E giữ volume/IP thừa là tiếp tục lãng phí.", "keyword": "Cost = lifecycle + commitment for steady baseline"}, {"n": 65, "text": "A company must protect sensitive S3 data with encryption and controlled access. Which TWO configurations together provide strong protection for data at rest and in transit/access control? (Select TWO)", "options": {"A": "Enable default encryption with SSE-KMS using a customer managed key and restrict key usage via the KMS key policy.", "B": "Require TLS (aws:SecureTransport) and deny non-TLS requests in the bucket policy, combined with least-privilege bucket policies.", "C": "Make the bucket public so encryption can be validated by anyone.", "D": "Disable S3 Block Public Access to simplify access.", "E": "Store access keys for the bucket in a public code repository."}, "answers": ["A", "B"], "multi": true, "explanation": "SSE-KMS với customer managed key + key policy kiểm soát được ai dùng key để mã hóa dữ liệu at rest, và ép TLS qua aws:SecureTransport + bucket policy least privilege bảo vệ dữ liệu in transit/access. C public bucket phá mọi kiểm soát. D tắt Block Public Access làm tăng rủi ro lộ dữ liệu. E để access key trong repo công khai là rò rỉ credential.", "keyword": "S3 protection = SSE-KMS + enforce TLS + least privilege"}]}, "2": {"title": "Đề mô phỏng SAA-C03 — Bộ 02", "minutes": 130, "passScore": 720, "questions": [{"n": 1, "text": "A gaming company uses Amazon DynamoDB for leaderboard data. Millions of players read the same popular items during tournaments, and the application requires single-digit millisecond latency to become microsecond latency for repeated reads. Provisioned throughput is already sufficient, but hot items cause uneven load. Which solution will provide in-memory caching with microsecond response times for DynamoDB?", "options": {"A": "Increase the DynamoDB table's read capacity units and enable adaptive capacity", "B": "Enable DynamoDB Accelerator (DAX) and route the application's DynamoDB API calls through the DAX cluster", "C": "Create an Amazon ElastiCache for Memcached cluster and manually cache every DynamoDB query result", "D": "Enable DynamoDB Streams and copy the data into Amazon OpenSearch Service for faster reads"}, "answers": ["B"], "multi": false, "explanation": "DAX là cache in-memory được thiết kế riêng cho DynamoDB, cho độ trễ microsecond với các API tương thích DynamoDB. Tăng RCU không tạo cache; ElastiCache phải tự quản lý logic cache và không tích hợp trực tiếp; Streams/OpenSearch không phải cache đọc cho DynamoDB.", "keyword": "DynamoDB DAX microsecond cache"}, {"n": 2, "text": "A serverless API experiences sudden traffic spikes. During spikes, downstream Amazon DynamoDB writes are overwhelmed and some Lambda invocations are throttled. The company wants Lambda functions that process orders to never exceed a safe maximum number of simultaneous executions, while other functions in the account remain unaffected. What should a solutions architect do?", "options": {"A": "Place the Lambda function inside a VPC with a NAT gateway", "B": "Set a reserved concurrency limit on the order-processing Lambda function", "C": "Set a provisioned concurrency limit on the order-processing Lambda function", "D": "Increase the Lambda function memory to the maximum value"}, "answers": ["B"], "multi": false, "explanation": "Reserved concurrency đặt giới hạn tối đa số execution environment chạy đồng thời cho đúng function đó, bảo vệ downstream và không ảnh hưởng function khác. Provisioned concurrency chỉ giữ môi trường khởi tạo sẵn để giảm cold start, không phải cơ chế chặn trên; tăng memory hay VPC/NAT không giới hạn concurrency.", "keyword": "Lambda reserved concurrency"}, {"n": 3, "text": "A payment application must process transactions in the exact order they were received and must ensure each transaction is processed exactly once, even when producers retry sending the same message. Standard queues have caused duplicate charges. Which solution meets these requirements?", "options": {"A": "Use an Amazon SQS FIFO queue with message deduplication enabled and a message group ID per account", "B": "Use an Amazon SQS standard queue with long polling enabled", "C": "Use an Amazon SNS standard topic with message filtering", "D": "Use an Amazon SQS standard queue with a dead-letter queue"}, "answers": ["A"], "multi": false, "explanation": "SQS FIFO đảm bảo ordering trong mỗi message group và deduplication giúp xử lý exactly-once trong cửa sổ deduplication. Standard queue chỉ best-effort ordering và at-least-once nên gây trùng; SNS standard và DLQ không tự tạo ordering/exactly-once.", "keyword": "SQS FIFO ordering deduplication exactly-once"}, {"n": 4, "text": "A company runs an Amazon Aurora PostgreSQL cluster in one AWS Region for a global application. The company requires a disaster recovery solution in a second Region with a recovery point objective (RPO) of about 1 second and a recovery time objective (RTO) of less than 1 minute for cross-Region failover. Which solution meets these requirements with the least operational effort?", "options": {"A": "Take hourly Aurora snapshots and copy them to the second Region", "B": "Use an Aurora Global Database with a secondary cluster in the disaster recovery Region", "C": "Use AWS Backup to copy Aurora backups to the second Region once a day", "D": "Create Aurora read replicas in the second Region and manually promote one during a disaster"}, "answers": ["B"], "multi": false, "explanation": "Aurora Global Database replicate sang Region phụ với độ trễ thường khoảng 1 giây và hỗ trợ failover nhanh ở mức dưới 1 phút, ít vận hành nhất cho RPO/RTO này. Snapshot/Backup theo giờ hoặc theo ngày có RPO quá lớn; read replica cross-Region phải promote thủ công và chậm hơn.", "keyword": "Aurora Global Database RPO 1s RTO"}, {"n": 5, "text": "A social application needs a cache that supports sorted sets for a leaderboard, pub/sub messaging, and data persistence. The cache must rank users by score in real time. Which Amazon ElastiCache option should a solutions architect choose?", "options": {"A": "ElastiCache for Memcached with cluster mode enabled", "B": "ElastiCache for Redis with sorted sets", "C": "ElastiCache for Memcached with write-through caching", "D": "Amazon DynamoDB Accelerator (DAX)"}, "answers": ["B"], "multi": false, "explanation": "Redis hỗ trợ sorted sets để xếp hạng leaderboard, pub/sub và persistence — đúng các tính năng nâng cao đề bài yêu cầu. Memcached đơn giản, đa luồng nhưng không có sorted sets/pub-sub/persistence; DAX chỉ là cache cho DynamoDB.", "keyword": "ElastiCache Redis sorted sets pub/sub"}, {"n": 6, "text": "A media company stores thousands of large video files that are uploaded once and downloaded many times by users worldwide. The files do not need to be mounted as a file system, and the company wants the most durable and cost-effective storage for this access pattern. Which storage service should be used?", "options": {"A": "Amazon S3 Standard storage", "B": "Amazon Elastic File System (Amazon EFS) with the General Purpose performance mode", "C": "Amazon Elastic Block Store (Amazon EBS) volumes attached to EC2 instances", "D": "Instance store volumes on Amazon EC2 instances"}, "answers": ["A"], "multi": false, "explanation": "Video là object tải lên một lần, đọc nhiều lần, không cần mount file system — S3 Standard cho durability rất cao và chi phí hợp lý nhất. EBS chỉ gắn với EC2 và không chia sẻ toàn cầu; EFS đắt hơn và thừa tính năng POSIX; instance store mất dữ liệu khi instance dừng.", "keyword": "S3 object storage vs EBS vs EFS"}, {"n": 7, "text": "A company stores a database password used by an application on Amazon EC2. Regulations require the password to be rotated automatically every 30 days without redeploying the application, and the application must always retrieve the current password. Which solution meets these requirements?", "options": {"A": "Store the password in AWS Secrets Manager and enable automatic rotation with a Lambda function", "B": "Store the password in an encrypted Amazon EBS volume and create a new volume every 30 days", "C": "Store the password in AWS Systems Manager Parameter Store as a plain text parameter", "D": "Store the password in an Amazon S3 bucket with versioning enabled"}, "answers": ["A"], "multi": false, "explanation": "Secrets Manager có automatic rotation bằng Lambda theo lịch (ví dụ 30 ngày) và ứng dụng luôn lấy secret hiện hành qua API. Parameter Store dạng plain text không an toàn và không tự xoay mật khẩu DB; EBS/S3 versioning không phải cơ chế rotation cho credential.", "keyword": "Secrets Manager automatic rotation"}, {"n": 8, "text": "A public web application is exposed through an Application Load Balancer. The security team wants protection against common web exploits such as SQL injection and cross-site scripting by using rules that AWS maintains and updates. Which solution should a solutions architect implement?", "options": {"A": "Enable Amazon GuardDuty and Amazon Inspector for the account", "B": "Enable AWS Shield Advanced on the Application Load Balancer", "C": "Attach AWS WAF to the Application Load Balancer and enable AWS Managed Rules", "D": "Add restrictive rules to the security group of the Application Load Balancer"}, "answers": ["C"], "multi": false, "explanation": "WAF gắn với ALB và dùng AWS Managed Rules để chặn các exploit phổ biến như SQL injection/XSS, rule được AWS duy trì cập nhật. Shield tập trung vào DDoS; security group chỉ lọc IP/port; GuardDuty/Inspector là dịch vụ phát hiện, không chặn request ở ALB.", "keyword": "WAF AWS Managed Rules ALB"}, {"n": 9, "text": "Several private subnets route internet traffic through a single NAT gateway, which generates high data processing charges. Instances in the private subnets mostly access Amazon S3 and Amazon DynamoDB. How can a solutions architect reduce NAT gateway costs for this traffic?", "options": {"A": "Move the instances into public subnets and assign Elastic IP addresses", "B": "Replace the NAT gateway with a NAT instance in a public subnet", "C": "Create gateway VPC endpoints for Amazon S3 and Amazon DynamoDB and add routes for them in the private route tables", "D": "Enable NAT gateway flow logs and delete the NAT gateway during weekends"}, "answers": ["C"], "multi": false, "explanation": "Gateway VPC endpoint cho S3 và DynamoDB miễn phí, đưa traffic ra khỏi NAT gateway nên cắt chi phí xử lý NAT cho phần traffic chiếm đa số này. NAT instance kém tin cậy/hiệu năng hơn; chuyển sang public subnet làm mất tính riêng tư; flow logs không giảm phí.", "keyword": "Gateway VPC Endpoint S3 DynamoDB NAT cost"}, {"n": 10, "text": "A company runs a steady-state production database on Amazon EC2 that must run continuously for 3 years and cannot tolerate interruptions. A separate batch workload can be interrupted at any time. Which purchasing options are MOST cost-effective for each workload?", "options": {"A": "Dedicated Hosts for the database, and Reserved Instances for the batch workload", "B": "On-Demand Instances for both workloads", "C": "Spot Instances for the database, and On-Demand Instances for the batch workload", "D": "Compute Savings Plans or Reserved Instances for the database, and Spot Instances for the batch workload"}, "answers": ["D"], "multi": false, "explanation": "Workload ổn định chạy liên tục 3 năm nên dùng cam kết dài hạn như Savings Plans/Reserved Instances để giảm giá; workload batch chịu gián đoạn được thì Spot rẻ nhất. Spot cho database production không được gián đoạn là sai hoàn toàn; On-Demand cho cả hai không tối ưu chi phí.", "keyword": "Savings Plans Reserved vs Spot"}, {"n": 11, "text": "An event-driven application must route orders to different processing services based on the content of each event, such as order amount and Region. Producers should publish events without knowing which consumers will receive them, and new consumers must be added without changing producers. Which service should be used for content-based event routing?", "options": {"A": "Amazon EventBridge with event buses and rules that match event patterns", "B": "Amazon Kinesis Data Streams with enhanced fan-out", "C": "AWS Step Functions with parallel branches", "D": "Amazon Simple Queue Service (Amazon SQS) standard queues"}, "answers": ["A"], "multi": false, "explanation": "EventBridge dùng event bus và rules khớp event pattern theo nội dung (số tiền, Region...) để route mà producer không cần biết consumer. SQS là queue point-to-point, Kinesis là stream theo shard, Step Functions là orchestration workflow — đều không phải content-based event routing.", "keyword": "EventBridge event pattern routing"}, {"n": 12, "text": "A company wants one published order event to be delivered simultaneously to a billing service, a shipping service, and an analytics service. Each service must be able to process events independently, at its own pace, and must not lose events when a service is temporarily unavailable. (Select TWO)", "options": {"A": "Publish the event to a single Amazon DynamoDB table and require each service to scan the table", "B": "Subscribe an Amazon SQS queue for each service to the SNS topic so each service buffers its own copy", "C": "Invoke three Lambda functions directly from the producer in sequence", "D": "Publish the event to an Amazon SNS topic", "E": "Store the event in a single shared SQS queue that all three services poll competitively"}, "answers": ["B", "D"], "multi": true, "explanation": "Fanout chuẩn: publish một lần lên SNS topic (D), mỗi service đăng ký một SQS queue riêng (B) để buffer và xử lý độc lập theo tốc độ riêng, không mất event khi service tạm dừng. Một queue chung khiến các service tranh nhau message; gọi Lambda tuần tự tạo coupling; scan DynamoDB không phải messaging.", "keyword": "SNS SQS fanout decoupling"}, {"n": 13, "text": "A startup wants to run Docker containers for a web API without provisioning or managing servers or clusters. Traffic varies, and the team wants the least operational overhead while still integrating with an Application Load Balancer. Which compute option should a solutions architect recommend?", "options": {"A": "Amazon Elastic Kubernetes Service (Amazon EKS) with self-managed worker nodes", "B": "Amazon Elastic Container Service (Amazon ECS) with the AWS Fargate launch type", "C": "AWS Elastic Beanstalk with a Docker environment and custom capacity management", "D": "Amazon EC2 instances in an Auto Scaling group with the containers installed manually"}, "answers": ["B"], "multi": false, "explanation": "ECS với Fargate chạy container mà không cần provision/quản lý server hay cluster node — least operational overhead, vẫn gắn ALB được. EC2 tự quản lý và EKS self-managed nodes tốn vận hành hơn; Elastic Beanstalk vẫn phải quản capacity nhiều hơn Fargate.", "keyword": "ECS Fargate serverless containers"}, {"n": 14, "text": "A business process involves receiving an order, checking inventory, charging a payment, and arranging shipment. Some steps run in parallel, failed steps must be retried with backoff, and the entire workflow state must be visible and auditable for up to several weeks. Which AWS service is MOST suitable to orchestrate this workflow?", "options": {"A": "AWS Lambda functions that call each other directly", "B": "Amazon EventBridge scheduled rules", "C": "AWS Step Functions state machines", "D": "Amazon Simple Queue Service (Amazon SQS) with visibility timeouts"}, "answers": ["C"], "multi": false, "explanation": "Step Functions là orchestrator có state, retry/backoff, parallel branches và lịch sử thực thi trực quan, kiểm toán được — đúng bản chất workflow nhiều bước dài ngày. SQS chỉ là queue, EventBridge rules không quản state workflow, Lambda gọi nhau trực tiếp khó theo dõi và dễ lỗi dây chuyền.", "keyword": "Step Functions orchestration retry"}, {"n": 15, "text": "A company must ingest a continuous stream of clickstream records at up to 800 MB per second for real-time analytics. Multiple independent applications need to read the same stream with their own read positions, and the data must be replayable for 7 days. Which service meets these requirements?", "options": {"A": "Amazon Simple Queue Service (Amazon SQS) FIFO queues", "B": "Amazon MSK Serverless with a single partition", "C": "Amazon Kinesis Data Firehose", "D": "Amazon Kinesis Data Streams with extended retention"}, "answers": ["D"], "multi": false, "explanation": "Kinesis Data Streams phục vụ ingest tốc độ cao, nhiều consumer đọc độc lập theo position riêng và replay được trong thời gian retention (kéo dài tới 365 ngày). Firehose là delivery gần real-time vào đích, không cho nhiều consumer đọc/replay tùy ý; SQS và MSK một partition không đáp ứng throughput/mô hình này.", "keyword": "Kinesis Data Streams replay multiple consumers"}, {"n": 16, "text": "Analysts need to run ad hoc SQL queries directly on several terabytes of JSON and Parquet data stored in Amazon S3, without provisioning servers. The data structure must be cataloged so table definitions can be reused across queries. Which combination of services should be used?", "options": {"A": "Amazon Athena for queries and AWS Glue Data Catalog for table metadata", "B": "Amazon Redshift for queries and Amazon RDS for table metadata", "C": "Amazon EMR for queries and Amazon DynamoDB for table metadata", "D": "Amazon Kinesis Data Analytics for queries and AWS Lake Formation for table metadata only"}, "answers": ["A"], "multi": false, "explanation": "Athena truy vấn SQL serverless trực tiếp trên S3, còn Glue Data Catalog lưu metadata bảng dùng chung cho Athena/EMR/Redshift Spectrum. Các cặp còn lại hoặc phải provision cluster, hoặc dùng sai dịch vụ làm catalog.", "keyword": "Athena Glue Data Catalog serverless SQL"}, {"n": 17, "text": "A new application uses Amazon DynamoDB. Traffic is highly unpredictable, with long idle periods followed by sudden large spikes. The operations team does not want to forecast capacity or manage throughput settings. Which DynamoDB capacity mode is MOST appropriate?", "options": {"A": "Provisioned capacity without Auto Scaling", "B": "Provisioned capacity with Auto Scaling", "C": "On-demand capacity mode", "D": "Reserved capacity with provisioned throughput"}, "answers": ["C"], "multi": false, "explanation": "On-demand tự trả theo request, không cần dự báo hay quản lý capacity, phù hợp traffic khó đoán với đỉnh đột ngột xen thời gian rỗng. Provisioned (dù có Auto Scaling) vẫn phải đặt mức nền và phản ứng chậm hơn với spike lớn; reserved capacity không dành cho mô hình này.", "keyword": "DynamoDB on-demand vs provisioned"}, {"n": 18, "text": "An AWS Lambda function that transcodes video files regularly needs 45 minutes to complete, but Lambda stops the work before it finishes. The processing is container-based and does not require a stateful server. Which solution should a solutions architect recommend?", "options": {"A": "Increase the Lambda function memory to 10 GB to make it finish faster", "B": "Move the workload to containers on AWS Fargate orchestrated as a longer-running task", "C": "Store the video in Amazon S3 Glacier and process it after retrieval", "D": "Split the Lambda function into smaller functions chained by Amazon SQS and keep each run under the Lambda timeout"}, "answers": ["B"], "multi": false, "explanation": "Lambda giới hạn thời gian chạy tối đa 15 phút nên job 45 phút không thể ở lại Lambda; chuyển sang container trên Fargate chạy task dài hạn là hướng chuẩn. Tăng memory chỉ tăng CPU/mạng chứ không nâng timeout; chia nhỏ bằng SQS phức tạp và không cần thiết khi workload đã đóng gói container.", "keyword": "Lambda 15 minute limit Fargate long-running"}, {"n": 19, "text": "A queue-based worker occasionally takes longer than expected to process a message. Other workers then receive and process the same message, causing duplicate work. Processed messages that repeatedly fail must be isolated for investigation. Which combination addresses this problem in Amazon SQS?", "options": {"A": "Enable FIFO ordering and reduce the message retention period to 60 seconds", "B": "Increase the visibility timeout to exceed processing time and configure a dead-letter queue with a maximum receive count", "C": "Use long polling and delete messages before processing begins", "D": "Shorten the visibility timeout and disable dead-letter queues"}, "answers": ["B"], "multi": false, "explanation": "Visibility timeout phải dài hơn thời gian xử lý để message không xuất hiện lại cho worker khác giữa chừng; DLQ với maxReceiveCount cách ly message lỗi lặp lại để điều tra. Rút ngắn timeout làm trùng lặp nặng hơn; xóa message trước khi xử lý gây mất dữ liệu.", "keyword": "SQS visibility timeout DLQ maxReceiveCount"}, {"n": 20, "text": "A development database on Amazon Aurora PostgreSQL has variable usage that drops to near zero at night and spikes during tests. The company wants the database capacity to scale automatically and to pay only for capacity used, without managing instances. Which option should be used?", "options": {"A": "Amazon RDS for PostgreSQL with storage Auto Scaling only", "B": "Aurora Provisioned with the smallest instance class", "C": "Aurora Serverless v2 configured with minimum and maximum Aurora Capacity Units (ACUs) so capacity scales automatically with usage", "D": "Amazon DynamoDB on-demand tables migrated from PostgreSQL"}, "answers": ["C"], "multi": false, "explanation": "Aurora Serverless v2 tự scale capacity theo ACU trong khoảng min–max đã cấu hình, phù hợp usage biến động mạnh và không phải quản lý instance. RDS storage Auto Scaling chỉ mở rộng storage, không scale compute; Aurora Provisioned instance nhỏ nhất vẫn chạy (và tính phí) 24/7.", "keyword": "Aurora Serverless v2 ACU scaling"}, {"n": 21, "text": "A read-heavy application uses Amazon ElastiCache for Redis in front of a database. Most reads are for a small set of popular items, and the application can tolerate occasionally stale data for a few minutes. The team wants the simplest caching strategy that populates the cache only when data is actually requested. Which strategy should be used?", "options": {"A": "Lazy loading (cache-aside)", "B": "Write-through caching", "C": "Write-behind (write-back) caching", "D": "Refresh-ahead caching managed by the database"}, "answers": ["A"], "multi": false, "explanation": "Lazy loading (cache-aside) chỉ nạp dữ liệu vào cache khi có request thực tế và miss — đơn giản nhất, chịu được dữ liệu hơi cũ trong vài phút như đề bài. Write-through ghi đồng thời cache+DB mỗi lần write (mạnh về tươi nhưng phức tạp hơn); write-behind ghi cache trước, DB sau; refresh-ahead không phải lựa chọn đơn giản nhất ở đây.", "keyword": "ElastiCache lazy loading cache-aside vs write-through"}, {"n": 22, "text": "A company stores compliance documents in Amazon S3. The documents are accessed frequently for 30 days, occasionally for the next 90 days, and almost never afterwards, but they must be retained for 7 years and remain retrievable within hours. Which lifecycle design is MOST cost-effective?", "options": {"A": "Transition objects to S3 One Zone-IA after 30 days and delete them after 120 days", "B": "Keep the objects in S3 Standard for the full 7 years", "C": "Transition objects to S3 Standard-IA after 30 days and to S3 Glacier Flexible Retrieval after 120 days, with expiration after 7 years", "D": "Copy the objects to Amazon EFS after 30 days and to Amazon EBS snapshots after 120 days"}, "answers": ["C"], "multi": false, "explanation": "Lifecycle chuyển dần Standard → Standard-IA sau 30 ngày → Glacier Flexible Retrieval sau 120 ngày rồi expire sau 7 năm khớp đúng tần suất truy cập giảm dần và yêu cầu lấy lại trong vài giờ. Giữ Standard 7 năm tốn nhất; One Zone-IA kém durable hơn cho compliance và xóa sau 120 ngày vi phạm retention 7 năm.", "keyword": "S3 Lifecycle Standard-IA Glacier Flexible Retrieval"}, {"n": 23, "text": "A retail company needs an Amazon DynamoDB table that is actively readable and writable in two AWS Regions at the same time. Users in each Region must write to their local Region with low latency, and changes must replicate automatically between Regions. Which DynamoDB feature meets these requirements?", "options": {"A": "DynamoDB export to Amazon S3 with cross-Region replication", "B": "DynamoDB Streams with a Lambda function that copies items to the other Region", "C": "DynamoDB point-in-time recovery with cross-Region backup copies", "D": "DynamoDB global tables"}, "answers": ["D"], "multi": false, "explanation": "Global Tables cho phép đọc/ghi chủ động ở nhiều Region (multi-Region active-active) với replication tự động và độ trễ thấp tại Region local. Streams + Lambda là giải pháp tự chế một chiều, tốn vận hành; PITR và export to S3 chỉ phục vụ backup/export, không phải active-active.", "keyword": "DynamoDB Global Tables active-active"}, {"n": 24, "text": "Whenever a new item is added to an Amazon DynamoDB table, a downstream process must update a search index and send a notification. The process must react to inserts and updates only, without continuously polling the table. Which solution should be used?", "options": {"A": "Enable DynamoDB Streams and use an AWS Lambda function as the stream consumer", "B": "Create an Amazon SQS queue and require producers to send duplicate messages", "C": "Enable DynamoDB Accelerator (DAX) and query the cache for changed items", "D": "Schedule an Amazon EventBridge rule to scan the DynamoDB table every minute"}, "answers": ["A"], "multi": false, "explanation": "DynamoDB Streams ghi lại mọi thay đổi insert/update theo thứ tự và Lambda là consumer event-driven chuẩn, không cần polling. DAX là cache đọc, không phát sự kiện thay đổi; EventBridge scan định kỳ là polling trá hình; bắt producer gửi trùng vào SQS tạo coupling và dễ sót.", "keyword": "DynamoDB Streams Lambda trigger"}, {"n": 25, "text": "An API built with Amazon API Gateway and AWS Lambda serves product data that changes only every few minutes. Repeated identical requests increase Lambda invocations and latency. Which API Gateway feature will reduce backend calls for repeated responses?", "options": {"A": "Convert the REST API to a WebSocket API", "B": "Enable API Gateway caching for the stage with an appropriate TTL", "C": "Enable API Gateway request validation", "D": "Use a usage plan with a lower quota"}, "answers": ["B"], "multi": false, "explanation": "Bật caching ở stage của API Gateway với TTL phù hợp sẽ trả response đã cache cho request lặp lại, giảm lần gọi Lambda và giảm độ trễ. Request validation chỉ kiểm tra input; usage plan để giới hạn quota/throttle; WebSocket API phục vụ giao tiếp hai chiều, không phải caching.", "keyword": "API Gateway caching TTL"}, {"n": 26, "text": "An application uses Amazon DynamoDB. Each authenticated user must be allowed to read and write only items where the partition key equals that user's ID. No application code change should be trusted to enforce this isolation alone. How can this be enforced in IAM?", "options": {"A": "Enable DynamoDB Streams and audit access after the fact", "B": "Enable DynamoDB encryption at rest with a customer managed KMS key", "C": "Give each user a separate DynamoDB table", "D": "Use an IAM policy with a condition that uses dynamodb:LeadingKeys tied to the user's identity"}, "answers": ["D"], "multi": false, "explanation": "Điều kiện dynamodb:LeadingKeys trong IAM policy giới hạn user chỉ truy cập item có partition key bằng định danh của chính họ — row-level access control thực thi ở tầng IAM. Mỗi user một bảng không scale; encryption và Streams không kiểm soát ai được đọc item nào.", "keyword": "DynamoDB LeadingKeys fine-grained access"}, {"n": 27, "text": "A company must encrypt Amazon S3 objects with keys it controls and audits. Every use of the encryption key must be logged, and the company must be able to disable the key to immediately block access to the data. Which approach meets these requirements?", "options": {"A": "Use server-side encryption with Amazon S3 managed keys (SSE-S3)", "B": "Use server-side encryption with AWS KMS keys (SSE-KMS) using a customer managed key", "C": "Enable S3 Bucket Versioning and MFA Delete", "D": "Use client-side compression before uploading objects to Amazon S3"}, "answers": ["B"], "multi": false, "explanation": "SSE-KMS với customer managed key cho phép kiểm soát key policy, audit mọi lần dùng key qua CloudTrail và disable key để chặn truy cập ngay. SSE-S3 dùng key do S3 quản lý nên không kiểm soát/audit ở mức key của mình; versioning/MFA Delete và nén không phải mã hóa do mình kiểm soát.", "keyword": "SSE-KMS customer managed key"}, {"n": 28, "text": "Private subnets have no internet route. Applications on Amazon EC2 in those subnets need frequent access to Amazon S3 and Amazon DynamoDB, and the security team wants this traffic to stay on the AWS network without traversing the internet. Which solution is MOST appropriate and cost-effective?", "options": {"A": "Create interface VPC endpoints powered by AWS PrivateLink for Amazon S3 and Amazon DynamoDB", "B": "Peer the VPC with another VPC that has an internet gateway", "C": "Deploy a NAT gateway in each private subnet", "D": "Create gateway VPC endpoints for Amazon S3 and Amazon DynamoDB"}, "answers": ["D"], "multi": false, "explanation": "S3 và DynamoDB hỗ trợ gateway endpoint — miễn phí, traffic đi trong mạng AWS qua route table, không cần NAT/internet. Interface endpoint (PrivateLink) tính phí theo giờ/GB và không cần thiết cho hai dịch vụ này; NAT gateway tốn phí và kém riêng tư hơn cho use case này.", "keyword": "Gateway endpoint free S3 DynamoDB"}, {"n": 29, "text": "A company's website is protected by AWS Shield Standard. After a large, sophisticated Layer 7 DDoS attack, the company needs 24/7 access to the AWS DDoS Response Team, cost protection for scaling during attacks, and advanced attack diagnostics. Which service should the company use?", "options": {"A": "AWS Network Firewall", "B": "AWS WAF with AWS Managed Rules only", "C": "Amazon GuardDuty", "D": "AWS Shield Advanced"}, "answers": ["D"], "multi": false, "explanation": "Shield Advanced bổ sung đội DDoS Response Team 24/7, cost protection và chẩn đoán nâng cao cho các cuộc tấn công phức tạp — Shield Standard (miễn phí, mặc định) không có các quyền lợi này. WAF chặn exploit lớp ứng dụng, GuardDuty phát hiện đe dọa, Network Firewall lọc traffic VPC — không thay thế Shield Advanced.", "keyword": "Shield Standard vs Shield Advanced DRT"}, {"n": 30, "text": "A development team needs to store a small configuration value securely and retrieve it from Lambda functions. (Select TWO statements that correctly distinguish the services.)", "options": {"A": "AWS Secrets Manager stores values in plain text by default with no encryption option", "B": "AWS Secrets Manager supports automatic rotation of secrets using Lambda functions", "C": "AWS Systems Manager Parameter Store cannot encrypt parameters with AWS KMS", "D": "Both services require the secret to be stored in an Amazon S3 bucket", "E": "AWS Systems Manager Parameter Store SecureString parameters can be used for secrets but automatic rotation is a native Secrets Manager feature, not a native Parameter Store feature"}, "answers": ["B", "E"], "multi": true, "explanation": "(B) Secrets Manager có sẵn automatic rotation bằng Lambda — tính năng phân biệt cốt lõi. (E) Parameter Store SecureString cũng lưu secret được mã hóa KMS nhưng không có rotation tự động native. (A) sai vì Secrets Manager luôn mã hóa; (C) sai vì SecureString mã hóa bằng KMS được; (D) sai vì không dịch vụ nào lưu secret trong S3.", "keyword": "Secrets Manager rotation vs Parameter Store SecureString"}, {"n": 31, "text": "A company exposes a web application through an Application Load Balancer and wants HTTPS with a certificate that is automatically renewed by AWS. The domain's DNS is managed outside AWS. Which solution should be used?", "options": {"A": "Request a public certificate in AWS Certificate Manager (ACM), validate it, and attach it to the ALB HTTPS listener", "B": "Generate a self-signed certificate on each EC2 instance and open port 80 on the ALB", "C": "Store a certificate in AWS Secrets Manager and attach it directly to the ALB", "D": "Enable AWS WAF on the ALB and use its default certificate"}, "answers": ["A"], "multi": false, "explanation": "ACM cấp chứng chỉ public, tự gia hạn và gắn trực tiếp vào HTTPS listener của ALB; DNS ngoài AWS vẫn validate được qua DNS/EMAIL validation. Self-signed không được trình duyệt tin cậy và không tự gia hạn; Secrets Manager/WAF không phải nơi gắn chứng chỉ cho ALB.", "keyword": "ACM certificate ALB HTTPS"}, {"n": 32, "text": "A new Amazon S3 bucket must never be publicly accessible, even if a future bucket policy or ACL mistakenly grants public access. The compliance team also requires least-privilege access for a single application role. Which control provides the account- and bucket-level block?", "options": {"A": "Enable S3 Versioning and Object Lock on the bucket", "B": "Create an AWS WAF web ACL for the bucket", "C": "Enable server access logging on the bucket", "D": "Enable S3 Block Public Access settings on the bucket"}, "answers": ["D"], "multi": false, "explanation": "Block Public Access ghi đè mọi bucket policy/ACL cố tình hay vô ý cấp public, ở cả cấp bucket và account — đúng lớp bảo vệ đề bài yêu cầu. Versioning/Object Lock chống xóa/sửa, logging chỉ ghi nhật ký, WAF không áp dụng cho S3 theo cách này.", "keyword": "S3 Block Public Access"}, {"n": 33, "text": "A security team needs to find which IAM user made a specific Amazon S3 API call 60 days ago and needs to run SQL queries over the historical API activity without building a server. Which solution should be used?", "options": {"A": "Query AWS CloudTrail events stored in Amazon S3 by using Amazon Athena", "B": "Enable Amazon GuardDuty findings and search them in the console", "C": "Download AWS Cost and Usage Reports and filter by user", "D": "Review Amazon CloudWatch metrics for the S3 bucket"}, "answers": ["A"], "multi": false, "explanation": "CloudTrail ghi lại API call và lưu log vào S3; Athena truy vấn SQL serverless trực tiếp trên các file log đó để tìm user/thao tác 60 ngày trước. CloudWatch metrics không chứa danh tính người gọi API; GuardDuty là findings bảo mật; Cost and Usage Reports phục vụ chi phí, không phải audit API.", "keyword": "CloudTrail Athena audit query"}, {"n": 34, "text": "All new Amazon EBS volumes in an account must be encrypted at rest by default, including volumes created from snapshots. The security team wants no unencrypted volumes to be created by developers. Which account-level setting should be enabled?", "options": {"A": "Enable AWS Config with a rule to delete unencrypted volumes after 30 days", "B": "Enable EBS encryption by default for the AWS Region", "C": "Enable Amazon Inspector for EC2 instances", "D": "Require MFA for all IAM users in the account"}, "answers": ["B"], "multi": false, "explanation": "Bật \"EBS encryption by default\" ở cấp Region khiến mọi volume mới (kể cả tạo từ snapshot) đều được mã hóa mặc định, nhà phát triển không tạo được volume trần. Config rule chỉ phát hiện/xử lý sau; Inspector quét lỗ hổng; MFA cho user không liên quan mã hóa volume.", "keyword": "EBS encryption by default"}, {"n": 35, "text": "An AWS Lambda function currently reads a database password from a plain text environment variable. Security review requires the password to be stored centrally, encrypted, rotated, and retrieved at runtime instead of being kept in plain text. Which solution should a solutions architect implement?", "options": {"A": "Encrypt the Lambda deployment package and keep the password in the code", "B": "Store the password in AWS Secrets Manager and grant the Lambda execution role permission to retrieve it", "C": "Store the password in a DynamoDB table without encryption", "D": "Store the password in an Amazon S3 object with bucket encryption enabled"}, "answers": ["B"], "multi": false, "explanation": "Đưa mật khẩu vào Secrets Manager và cấp cho Lambda execution role quyền GetSecretValue là cách chuẩn: lưu trữ tập trung, mã hóa, xoay được, lấy tại runtime. Để mật khẩu trong code/gói deploy, S3 object hay DynamoDB không mã hóa đều giữ nguyên các vi phạm mà bài review đã chỉ ra.", "keyword": "Lambda Secrets Manager execution role"}, {"n": 36, "text": "An Application Load Balancer fronts a web application that is receiving SQL injection and cross-site scripting attempts in HTTP requests. The team wants to block these requests before they reach the application, using AWS-managed protections. Which solution should be used?", "options": {"A": "Add a network ACL that blocks the attackers' country", "B": "Increase the size of the EC2 instances behind the ALB", "C": "Enable Amazon CloudFront signed URLs for the application", "D": "Attach AWS WAF with the AWS Managed Rules SQL database and Core rule sets to the ALB"}, "answers": ["D"], "multi": false, "explanation": "WAF gắn ALB với Managed Rules nhóm SQL database và Core rule set sẽ chặn SQLi/XSS ở biên trước khi request tới ứng dụng. Network ACL không hiểu nội dung HTTP; signed URL kiểm soát truy cập nội dung CloudFront chứ không lọc payload tấn công; tăng size EC2 không chặn được gì.", "keyword": "WAF Managed Rules SQLi XSS"}, {"n": 37, "text": "A security team wants two different types of continuous detection. (Select TWO correct pairings.)", "options": {"A": "Amazon Inspector automatically assesses EC2 instances and container images for software vulnerabilities", "B": "Amazon Inspector provides a managed web application firewall for ALBs", "C": "Amazon GuardDuty analyzes logs to detect malicious activity and compromised credentials in an AWS account", "D": "Amazon GuardDuty patches operating system vulnerabilities on EC2 instances", "E": "Both services replace the need for IAM policies"}, "answers": ["A", "C"], "multi": true, "explanation": "(A) Inspector tự động đánh giá lỗ hổng phần mềm trên EC2 và container image. (C) GuardDuty phân tích log (CloudTrail, VPC Flow, DNS...) để phát hiện hoạt động độc hại và credential bị xâm phạm. GuardDuty không vá lỗi, Inspector không phải firewall — hai ý (B) và (D) hoán đổi sai vai trò; (E) sai vì IAM vẫn bắt buộc.", "keyword": "GuardDuty threat detection Inspector vulnerability"}, {"n": 38, "text": "Containers running on Amazon ECS must access Amazon S3 and Amazon DynamoDB with permissions that apply only to the running containers, not to the underlying hosts or other tasks. Credentials must be provided automatically and rotated by AWS. Which IAM construct should be used?", "options": {"A": "An instance role shared by all ECS container instances with administrator access", "B": "An ECS task role assigned to the task definition", "C": "A bucket policy that allows access from any principal", "D": "An IAM user with access keys stored in the container image"}, "answers": ["B"], "multi": false, "explanation": "ECS task role cấp credential tạm thời đúng phạm vi cho chính các container trong task, do AWS tự cấp và xoay. Instance role dùng chung cho mọi task trên host và dễ thừa quyền; access key của IAM user đóng gói trong image là chống chỉ định; bucket policy mở cho mọi principal phá vỡ least privilege.", "keyword": "ECS task role vs instance role"}, {"n": 39, "text": "A company uses Amazon SQS queues that contain sensitive data. Compliance requires encryption at rest with a customer managed AWS KMS key, and only a specific application role may decrypt messages. Which configuration meets these requirements?", "options": {"A": "Use an HTTPS endpoint for SQS and rely only on transport encryption", "B": "Enable SQS message deduplication and FIFO ordering", "C": "Store messages in an encrypted Amazon EBS volume instead of SQS", "D": "Enable server-side encryption with a customer managed KMS key on the queue and control access through the key policy and IAM policy"}, "answers": ["D"], "multi": false, "explanation": "Bật SSE trên queue bằng customer managed KMS key và kiểm soát qua key policy + IAM policy mới đáp ứng mã hóa at rest do mình kiểm soát và chỉ role chỉ định mới giải mã được. HTTPS chỉ mã hóa in transit; deduplication/FIFO là tính năng ordering, không phải mã hóa.", "keyword": "SQS SSE-KMS key policy"}, {"n": 40, "text": "An Amazon Aurora MySQL cluster stores sensitive data. The company wants database users to authenticate using IAM credentials instead of static database passwords, in addition to encryption at rest. Which Aurora feature should be enabled?", "options": {"A": "Aurora Serverless auto pause", "B": "IAM database authentication", "C": "Aurora Global Database", "D": "Aurora backtrack"}, "answers": ["B"], "multi": false, "explanation": "IAM database authentication cho phép đăng nhập Aurora bằng token sinh từ thông tin xác thực IAM thay cho mật khẩu tĩnh. Global Database là replication cross-Region, backtrack là tua thời gian trong cluster, auto pause thuộc Serverless v1 — không liên quan xác thực.", "keyword": "Aurora IAM database authentication"}, {"n": 41, "text": "A team uses Amazon ElastiCache for Redis for session data. Compliance requires that data is encrypted while moving between clients and the cluster, and that clients must present an authentication token to connect. Which features should be enabled?", "options": {"A": "Lazy loading and TTL on session keys", "B": "Redis append-only file and cluster mode", "C": "In-transit encryption (TLS) and Redis AUTH", "D": "Memcached SASL and multi-threading"}, "answers": ["C"], "multi": false, "explanation": "In-transit encryption (TLS) mã hóa dữ liệu trên đường truyền và Redis AUTH yêu cầu token khi kết nối — đúng cặp yêu cầu compliance. AOF/cluster mode là tính năng durability/scale; SASL thuộc Memcached; lazy loading/TTL là chiến lược cache, không phải bảo mật.", "keyword": "ElastiCache Redis TLS AUTH encryption"}, {"n": 42, "text": "Analysts query sensitive data in Amazon S3 by using Amazon Athena. Different teams must have separate query limits and cost controls, and query results must be encrypted. Which Athena feature helps organize and control this usage?", "options": {"A": "Athena provisioned capacity with EC2 instances", "B": "Glue crawlers with automatic schema discovery only", "C": "Athena workgroups with per-workgroup settings for result locations, encryption, and bytes-scanned limits", "D": "S3 Object Lock on the query results bucket only"}, "answers": ["C"], "multi": false, "explanation": "Athena workgroups tách nhóm người dùng theo cấu hình riêng: vị trí/kiểu mã hóa của kết quả và giới hạn bytes scanned để kiểm soát chi phí. Crawler chỉ khám phá schema cho Glue Catalog; Object Lock trên bucket kết quả không tạo giới hạn truy vấn theo nhóm.", "keyword": "Athena workgroups cost control"}, {"n": 43, "text": "An AWS Step Functions workflow invokes several Lambda functions. Each function needs different, minimal permissions, and the workflow must not use a single highly privileged role for all steps. Which design follows least privilege?", "options": {"A": "Give the Step Functions state machine and all Lambda functions administrator access", "B": "Disable IAM roles and rely on resource policies on Amazon S3 only", "C": "Store one IAM user's access keys in the state machine definition", "D": "Create a separate IAM execution role for each Lambda function with only the permissions that function needs"}, "answers": ["D"], "multi": false, "explanation": "Mỗi Lambda một execution role riêng với quyền tối thiểu cho đúng việc của nó là least privilege chuẩn. Dùng một role admin chung, nhúng access key vào state machine, hay bỏ IAM roles đều phá vỡ nguyên tắc này.", "keyword": "Least privilege Lambda execution role"}, {"n": 44, "text": "An AWS Lambda function is triggered by an Amazon SQS queue. During traffic spikes, messages must not be lost, failed messages must be retried a limited number of times and then isolated, and successful messages must be removed automatically. Which configuration should be used?", "options": {"A": "Configure the Lambda function to poll the queue manually with a scheduled rule and delete all messages on each run", "B": "Configure the queue as the Lambda event source with a dead-letter queue and a maxReceiveCount on the source queue's redrive policy", "C": "Use an SNS topic instead of SQS and disable Lambda retries", "D": "Increase Lambda memory and set the queue retention period to 60 seconds"}, "answers": ["B"], "multi": false, "explanation": "Cấu hình SQS làm event source cho Lambda: message thành công tự bị xóa, message lỗi được nhận lại có giới hạn theo redrive policy rồi chuyển vào DLQ để cách ly. Tự poll bằng lịch và xóa toàn bộ gây mất dữ liệu; tăng memory không xử lý được retry/DLQ; đổi sang SNS làm mất tính buffer của queue.", "keyword": "Lambda SQS event source DLQ redrive"}, {"n": 45, "text": "A company runs an Amazon Aurora cluster with a primary instance and one read replica in the same Region. The application needs automatic failover to a synchronous standby with no data loss during an Availability Zone failure, rather than promotion of an asynchronous replica. Which configuration should a solutions architect recommend?", "options": {"A": "Use an Aurora Multi-AZ DB cluster deployment with a reader endpoint for failover", "B": "Keep only read replicas and rely on manual promotion", "C": "Take snapshots every hour and restore them during a failure", "D": "Use Aurora Global Database across two Regions"}, "answers": ["A"], "multi": false, "explanation": "Aurora Multi-AZ DB cluster deployment có writer và các reader ở nhiều AZ với replication đồng bộ ở tầng storage, failover tự động không mất dữ liệu khi một AZ lỗi. Read replica thường là bất đồng bộ và promote thủ công có thể mất dữ liệu; Global Database dành cho cross-Region; restore snapshot chậm và mất dữ liệu mới.", "keyword": "Aurora Multi-AZ cluster failover synchronous"}, {"n": 46, "text": "Multiple Amazon EC2 instances in different Availability Zones must read and write the same shared file system concurrently using standard POSIX semantics. The file system must be regional and highly available across AZs. Which storage service meets these requirements?", "options": {"A": "Amazon S3 mounted as a local file system on each instance", "B": "EC2 instance store volumes synchronized with a cron job", "C": "Amazon Elastic File System (Amazon EFS) in Regional mode mounted by instances in multiple AZs", "D": "A single Amazon EBS volume attached to instances in all AZs"}, "answers": ["C"], "multi": false, "explanation": "EFS Regional là file system POSIX dùng chung, mount đồng thời từ nhiều AZ — đúng yêu cầu shared file system đa AZ. EBS là block storage gắn theo AZ (không chia sẻ đa AZ theo cách này); S3 là object storage không có ngữ nghĩa POSIX; instance store là tạm thời và không dùng chung.", "keyword": "EFS shared POSIX multi-AZ"}, {"n": 47, "text": "A company must replicate objects from an Amazon S3 bucket in one Region to a bucket in another Region for disaster recovery. (Select TWO requirements for S3 Cross-Region Replication.)", "options": {"A": "Versioning must be enabled on both the source and destination buckets", "B": "The source bucket owner must have permissions to replicate objects, typically through an IAM role assumed by S3", "C": "Cross-Region Replication works only when both buckets have Block Public Access disabled", "D": "The destination bucket must be in the same Availability Zone as the source bucket", "E": "Objects must be stored in the S3 One Zone-IA storage class in both buckets"}, "answers": ["A", "B"], "multi": true, "explanation": "CRR yêu cầu versioning bật ở cả bucket nguồn và đích (A) và S3 cần quyền replicate thông qua IAM role do S3 assume (B). CRR hoạt động bình thường cùng Block Public Access, bucket đích nằm ở Region khác chứ không phải cùng AZ, và không bắt buộc One Zone-IA.", "keyword": "S3 Cross-Region Replication versioning IAM role"}, {"n": 48, "text": "An Amazon EventBridge bus routes events to several targets. Occasionally a target is unavailable and events fail delivery. The team must capture failed events, investigate them, and replay archived events after the target is fixed. Which EventBridge features should be used?", "options": {"A": "AWS Step Functions Catch blocks for every rule", "B": "Amazon SQS FIFO deduplication and message group IDs", "C": "Dead-letter queues for targets and event archive and replay", "D": "EventBridge Scheduler and input transformers only"}, "answers": ["C"], "multi": false, "explanation": "EventBridge hỗ trợ DLQ cho target để hứng event giao thất bại và tính năng archive/replay để phát lại event đã lưu sau khi target sửa xong. Scheduler/input transformer không xử lý delivery failure; FIFO deduplication và Catch của Step Functions thuộc dịch vụ khác.", "keyword": "EventBridge DLQ archive replay"}, {"n": 49, "text": "A containerized service runs on Amazon ECS behind an Application Load Balancer. The service must maintain a desired number of healthy tasks, replace unhealthy tasks automatically, and scale out when CPU utilization is high. Which ECS feature combination provides this?", "options": {"A": "A scheduled ECS task that runs once a day", "B": "A single standalone ECS task that is restarted manually", "C": "An ECS service with a desired count, ALB health checks, and Application Auto Scaling based on CPU utilization", "D": "An ECS task definition with host networking and no service"}, "answers": ["C"], "multi": false, "explanation": "ECS service duy trì desired count, thay task unhealthy dựa trên health check của ALB và kết hợp Application Auto Scaling theo CPU để scale — bộ ba chuẩn cho service luôn khỏe và đàn hồi. Task đơn lẻ/scheduled task không có cơ chế duy trì số lượng hay tự thay task lỗi.", "keyword": "ECS service desired count Auto Scaling"}, {"n": 50, "text": "An Amazon DynamoDB table holds critical order data. The company must be able to restore the table to any point in time within the last 35 days after accidental deletes or writes. Which DynamoDB feature should be enabled?", "options": {"A": "On-demand capacity mode", "B": "DynamoDB Accelerator (DAX)", "C": "DynamoDB Streams with a 24-hour retention window only", "D": "Point-in-time recovery (PITR)"}, "answers": ["D"], "multi": false, "explanation": "PITR sao lưu liên tục và cho restore về bất kỳ thời điểm nào trong tối đa 35 ngày — đúng kịch bản khôi phục sau xóa/ghi nhầm. Streams chỉ giữ thay đổi 24 giờ và là nguồn sự kiện, không phải backup; on-demand và DAX liên quan capacity/cache.", "keyword": "DynamoDB point-in-time recovery 35 days"}, {"n": 51, "text": "An AWS Lambda function that serves a latency-sensitive API has unpredictable cold starts that cause spikes above the required response time during business hours. The function is used continuously throughout the day. Which feature will keep execution environments initialized and ready to respond immediately?", "options": {"A": "Provisioned concurrency for the Lambda function", "B": "Reserved concurrency for the Lambda function", "C": "Increasing the function timeout to 15 minutes", "D": "Lambda SnapStart for Python functions only, with no other change"}, "answers": ["A"], "multi": false, "explanation": "Provisioned concurrency giữ sẵn môi trường đã khởi tạo nên request đến là chạy ngay, loại bỏ cold start cho workload dùng liên tục. Reserved concurrency chỉ đặt hạn mức tối đa/tối thiểu được đảm bảo, không khởi tạo sẵn môi trường; tăng timeout không liên quan độ trễ khởi động.", "keyword": "Lambda provisioned concurrency cold start"}, {"n": 52, "text": "An Amazon ElastiCache for Redis workload has grown beyond the memory and throughput of a single node. The team needs to partition data across multiple shards while retaining Redis data structures within each shard. Which configuration should be used?", "options": {"A": "DynamoDB Accelerator (DAX) with a larger cluster", "B": "Memcached with a single large node", "C": "Redis with cluster mode disabled and a larger node type only", "D": "Redis cluster mode enabled with multiple shards and replicas"}, "answers": ["D"], "multi": false, "explanation": "Bật cluster mode với nhiều shard sẽ phân mảnh dữ liệu để vượt giới hạn bộ nhớ/throughput của một node, vẫn giữ cấu trúc dữ liệu Redis trong từng shard. Tắt cluster mode rồi chỉ tăng node thì sớm chạm trần single node; Memcached và DAX không đáp ứng yêu cầu Redis này.", "keyword": "ElastiCache Redis cluster mode sharding"}, {"n": 53, "text": "An Amazon Kinesis Data Streams application experiences hot shards because many records share the same partition key. Throughput per shard is exceeded even though total stream capacity seems sufficient. What is the MOST appropriate first action?", "options": {"A": "Distribute records across more varied partition keys and add shards or switch the stream to on-demand capacity mode", "B": "Reduce the retention period to 24 hours", "C": "Enable server-side encryption with a customer managed KMS key", "D": "Convert the stream to Kinesis Data Firehose"}, "answers": ["A"], "multi": false, "explanation": "Hot shard sinh ra do partition key phân bố lệch: cần đa dạng hóa partition key để tải trải đều, đồng thời tăng shard hoặc chuyển sang on-demand mode khi tổng throughput tăng. Mã hóa, retention và Firehose không giải quyết nút cổ chai theo từng shard.", "keyword": "Kinesis hot shard partition key"}, {"n": 54, "text": "An application on Amazon EC2 needs a boot and data volume with consistently high IOPS and low latency for a transactional database, while a second workload needs a cost-effective general-purpose SSD volume with a balance of price and performance. Which pairing is correct?", "options": {"A": "st1 for the database, and Cold HDD (sc1) for the general-purpose workload", "B": "gp3 for the database with the lowest IOPS, and io2 for all general files", "C": "io2 or io2 Block Express for the database, and gp3 for the general-purpose workload", "D": "Instance store for the database with durability, and gp3 for backups only"}, "answers": ["C"], "multi": false, "explanation": "io2/io2 Block Express cho IOPS rất cao, ổn định và độ trễ thấp cho database giao dịch; gp3 là SSD đa dụng cân bằng giá/hiệu năng cho workload thông thường. st1/sc1 là HDD cho throughput/cold data, không hợp database cần IOPS; instance store không bền vững cho dữ liệu quan trọng.", "keyword": "EBS io2 vs gp3"}, {"n": 55, "text": "A reporting application must run read queries against an Amazon Aurora PostgreSQL cluster without affecting the performance of the primary writer. Replica lag must stay minimal and the reporting endpoint must automatically include new replicas. Which solution should be used?", "options": {"A": "Direct reporting queries to the cluster (writer) endpoint during off-peak hours only", "B": "Copy the Aurora data to Amazon S3 hourly and query it with the reporting application", "C": "Increase the primary instance size and run all queries on the writer", "D": "Create Aurora read replicas and direct reporting queries to the Aurora reader endpoint"}, "answers": ["D"], "multi": false, "explanation": "Aurora read replicas chia sẻ cùng storage layer nên lag rất thấp, và reader endpoint tự cân bằng, tự bổ sung replica mới — tách tải đọc khỏi writer đúng yêu cầu. Chạy report trên writer vẫn ảnh hưởng production; export S3 theo giờ dữ liệu cũ và chậm; tăng size writer không tách được tải.", "keyword": "Aurora read replica reader endpoint"}, {"n": 56, "text": "Users in multiple continents upload large files to a central Amazon S3 bucket. Uploads over long-distance networks are slow and unreliable for files larger than 1 GB. Which S3 practices will improve large uploads?", "options": {"A": "Compress all files into a single archive in S3 Glacier before users download them", "B": "Store large files on a single EBS volume and sync them nightly", "C": "Use multipart upload for large objects, and consider S3 Transfer Acceleration for long-distance uploads", "D": "Upload each large file in a single request over HTTP without retries"}, "answers": ["C"], "multi": false, "explanation": "Multipart upload chia file lớn thành các phần tải song song, thử lại từng phần — chuẩn cho file >100 MB; Transfer Acceleration tăng tốc đường dài qua CloudFront edge locations. Tải một request duy nhất dễ lỗi và không resume được; EBS/Glacier không phải kênh upload cho người dùng toàn cầu.", "keyword": "S3 multipart upload Transfer Acceleration"}, {"n": 57, "text": "A fault-tolerant batch processing workload runs on Amazon ECS and can handle interruptions with checkpointing. The workload does not need guaranteed capacity and cost is the main concern. (Select TWO best practices for this workload on Spot capacity.)", "options": {"A": "Design the application to checkpoint progress and handle task interruptions gracefully", "B": "Use Spot Instances for a latency-sensitive primary database with no replication", "C": "Store all intermediate state only in local container memory with no external storage", "D": "Use Spot Instances or Fargate Spot for the ECS tasks", "E": "Request the highest possible Spot price in a single Availability Zone to guarantee no interruptions"}, "answers": ["A", "D"], "multi": true, "explanation": "(D) Spot/Fargate Spot cho chi phí thấp nhất cho ECS task. (A) Vì Spot có thể bị thu hồi, ứng dụng bắt buộc phải checkpoint và chịu gián đoạn tốt — đề bài đã nêu rõ hai điều kiện này. Spot cho primary database không replication là chống chỉ định; giữ state chỉ trong bộ nhớ local và cố trả giá cao ở một AZ đều phá vỡ thiết kế chịu lỗi/giá rẻ.", "keyword": "Spot Fargate Spot checkpoint fault tolerant"}, {"n": 58, "text": "An AWS Lambda function is allocated 3 GB of memory but typically uses very little CPU and finishes quickly. Billing analysis suggests the function is over-provisioned for its workload, while another function is CPU-bound and finishes faster with more memory. Which principle should guide cost optimization for Lambda?", "options": {"A": "Always set every Lambda function to the maximum memory to reduce cost", "B": "Tune the memory allocation for each function, because memory also controls CPU, and measure duration versus cost to find the lowest total cost per invocation", "C": "Always set every Lambda function to the minimum memory to reduce cost", "D": "Increase the timeout setting to reduce the number of invocations billed"}, "answers": ["B"], "multi": false, "explanation": "Giá Lambda tính theo GB-second: tăng memory tăng CPU nên có thể rút ngắn duration đủ để tổng chi phí giảm, và ngược lại với function nhẹ. Vì vậy phải đo/tinh chỉnh từng function để tìm điểm chi phí thấp nhất. Đặt max hay min cho mọi function đều phung phí ở một đầu; timeout không quyết định chi phí mỗi invocation.", "keyword": "Lambda memory tuning GB-second cost"}, {"n": 59, "text": "A worker polls an Amazon SQS queue that is often empty. The application makes many empty ReceiveMessage calls, increasing cost and unnecessary API traffic. Which SQS feature reduces empty receives?", "options": {"A": "Enable short polling with WaitTimeSeconds set to 0", "B": "Enable FIFO ordering on a standard queue", "C": "Enable long polling by setting WaitTimeSeconds to a value greater than 0, such as 20 seconds", "D": "Reduce the message retention period to 60 seconds"}, "answers": ["C"], "multi": false, "explanation": "Long polling với WaitTimeSeconds > 0 (tối đa 20) khiến ReceiveMessage chờ tới khi có message thay vì trả rỗng ngay, cắt mạnh số lần receive rỗng và chi phí API. Short polling (0) chính là nguyên nhân gây receive rỗng liên tục; FIFO và retention không liên quan.", "keyword": "SQS long polling WaitTimeSeconds"}, {"n": 60, "text": "A VPC has private subnets in three Availability Zones, each with its own NAT gateway. Finance asks to reduce cost, while architecture requires high availability. A proposal suggests using a single NAT gateway for all AZs. Which statement correctly evaluates this tradeoff?", "options": {"A": "NAT gateways are free, so the number deployed does not affect cost", "B": "A single NAT gateway improves both cost and high availability in all cases", "C": "A single NAT gateway reduces cost but creates a single point of failure and can incur cross-AZ data transfer charges if one AZ fails or traffic crosses AZs", "D": "Each private subnet must use an internet gateway instead of a NAT gateway to save cost"}, "answers": ["C"], "multi": false, "explanation": "Một NAT gateway cho cả VPC rẻ hơn nhưng là single point of failure: AZ chứa nó lỗi thì các AZ khác mất đường ra internet, và traffic xuyên AZ còn phát sinh phí cross-AZ. NAT gateway tính phí theo giờ + theo GB xử lý nên số lượng ảnh hưởng trực tiếp chi phí; nó cũng không thể vừa rẻ vừa HA hơn phương án mỗi AZ một cái.", "keyword": "NAT Gateway cost vs high availability tradeoff"}, {"n": 61, "text": "A company commits to a consistent level of compute usage for 1 year across multiple instance families, Regions, and services including Amazon EC2, AWS Fargate, and AWS Lambda. The company wants the flexibility to change instance families without losing the discount. (Select TWO correct statements about Compute Savings Plans.)", "options": {"A": "Compute Savings Plans require the company to commit to a specific instance family in a specific Region", "B": "Compute Savings Plans provide capacity reservation in a specific Availability Zone", "C": "Compute Savings Plans offer flexibility to change instance family, size, Region, and compute service while retaining the discount commitment", "D": "Compute Savings Plans automatically apply across EC2, Fargate, and Lambda usage", "E": "Compute Savings Plans can be interrupted and reclaimed by AWS like Spot Instances"}, "answers": ["C", "D"], "multi": true, "explanation": "Compute Savings Plans cam kết mức dùng theo $/giờ và tự áp dụng linh hoạt qua EC2, Fargate, Lambda, thay đổi được family/size/Region (C, D). Cam kết cứng theo family/Region là của EC2 Instance Savings Plans/Reserved Instances; Savings Plans không giữ capacity theo AZ và không bị thu hồi như Spot.", "keyword": "Compute Savings Plans flexibility EC2 Fargate Lambda"}, {"n": 62, "text": "A session table in Amazon DynamoDB contains millions of expired session items that are no longer needed. Manually deleting them consumes write capacity and adds cost. Which DynamoDB feature deletes expired items automatically at no extra throughput cost?", "options": {"A": "Point-in-time recovery (PITR)", "B": "Time to Live (TTL) with an attribute that stores the expiry timestamp", "C": "DynamoDB Streams with a Lambda function that deletes items continuously", "D": "DynamoDB Accelerator (DAX) cache eviction"}, "answers": ["B"], "multi": false, "explanation": "TTL dùng attribute chứa timestamp hết hạn; DynamoDB tự xóa item đã hết hạn ở background mà không tốn write capacity. Streams + Lambda tự xóa vẫn tốn tài nguyên và phải vận hành; PITR là backup; DAX eviction chỉ là việc của cache, không dọn bảng gốc.", "keyword": "DynamoDB TTL free expiry deletion"}, {"n": 63, "text": "Analysts run Amazon Athena queries over data in Amazon S3. Queries are expensive because Athena scans large amounts of CSV data for every query, even when analysts filter by a single date. (Select TWO actions that will reduce Athena cost and improve performance.)", "options": {"A": "Disable the AWS Glue Data Catalog so every query scans all files", "B": "Convert the data to a columnar format such as Parquet", "C": "Store the data as many small uncompressed CSV files with no partitioning", "D": "Run queries more frequently so Athena caches the full data set permanently", "E": "Partition the data in S3 by the filter column, such as date, so queries scan only relevant partitions"}, "answers": ["B", "E"], "multi": true, "explanation": "Athena tính phí theo lượng data scan: Parquet dạng cột chỉ đọc các cột cần thiết (B) và partition theo cột lọc như date giúp bỏ qua toàn bộ partition không liên quan (E) — hai đòn giảm chi phí kinh điển. Nhiều file CSV nhỏ không partition làm scan toàn bộ; tắt Glue Catalog phá vỡ việc quản lý bảng; Athena không cache vĩnh viễn toàn bộ dataset.", "keyword": "Athena Parquet partitioning scan cost"}, {"n": 64, "text": "A shared file system on Amazon EFS contains project files. Most files are not accessed after 30 days, but must remain available with low latency when occasionally needed. Storage costs must be reduced without manual file movement. Which EFS feature should be used?", "options": {"A": "Enable EFS lifecycle management to transition infrequently accessed files to the EFS Infrequent Access (IA) storage class", "B": "Create a second EFS file system in another Region and replicate all files", "C": "Copy files manually to Amazon S3 Glacier and delete them from EFS after 30 days", "D": "Switch the file system to Max I/O performance mode"}, "answers": ["A"], "multi": false, "explanation": "EFS lifecycle management tự chuyển file ít truy cập sang lớp Infrequent Access rẻ hơn và tự chuyển về khi được truy cập lại, không cần thao tác thủ công. Sao chép tay sang Glacier rồi xóa khỏi EFS phá vỡ yêu cầu file vẫn sẵn sàng trên file system; Max I/O là chế độ hiệu năng, không giảm chi phí lưu trữ.", "keyword": "EFS lifecycle Infrequent Access"}, {"n": 65, "text": "A company must archive backup data in Amazon S3 for 5 years for compliance. The data is almost never accessed, but when an audit occurs it must be retrievable within a few hours. The company wants the lowest storage cost that still meets this retrieval requirement. Which S3 storage class is MOST appropriate?", "options": {"A": "S3 Standard-IA", "B": "S3 Intelligent-Tiering with no archive tiers enabled", "C": "S3 Glacier Flexible Retrieval", "D": "S3 Standard"}, "answers": ["C"], "multi": false, "explanation": "Glacier Flexible Retrieval cho chi phí lưu trữ rất thấp cho dữ liệu archive hiếm khi truy cập và vẫn lấy lại được trong vài giờ (expedited/standard) — khớp đúng retention 5 năm và yêu cầu audit. Standard/Standard-IA đắt hơn nhiều cho archive dài hạn; Intelligent-Tiering không bật archive tier thì không đạt mức giá archive.", "keyword": "S3 Glacier Flexible Retrieval archive hours"}]}, "3": {"title": "Đề mô phỏng SAA-C03 — Bộ 03", "minutes": 130, "passScore": 720, "questions": [{"n": 1, "text": "A company is building a complete three-tier web application. The web and application tiers must scale automatically, survive the loss of one Availability Zone, and the database tier must fail over automatically with no data loss during a planned AZ maintenance. Which architecture meets these requirements?", "options": {"A": "EC2 instances in one AZ behind an Application Load Balancer, with a single RDS instance and manual snapshots", "B": "Application Load Balancer across multiple AZs, an Auto Scaling group of EC2 instances in private subnets across multiple AZs, and Amazon RDS deployed with Multi-AZ", "C": "Network Load Balancer in one AZ, EC2 instances in public subnets, and Amazon DynamoDB with on-demand capacity", "D": "CloudFront, Amazon S3 static hosting, and a single EC2 instance running a self-managed database"}, "answers": ["B"], "multi": false, "explanation": "Kiến trúc 3-tier chuẩn HA: ALB và ASG trải nhiều AZ giúp tầng ứng dụng tự scale và chịu lỗi AZ. RDS Multi-AZ có standby đồng bộ, failover tự động nên không mất dữ liệu khi bảo trì hoặc sự cố AZ. Đặt instance ở private subnet cũng đúng thực hành bảo mật.", "keyword": "3-tier, Multi-AZ, ALB + ASG + RDS Multi-AZ"}, {"n": 2, "text": "A solutions architect is about to update a production CloudFormation stack that contains an RDS database and an Auto Scaling group. Before applying the update, the architect must preview exactly which resources will be added, modified, or replaced, and obtain approval. What should the architect do?", "options": {"A": "Enable termination protection and update the stack directly", "B": "Use CloudFormation drift detection on the stack", "C": "Create a change set for the stack, review the proposed changes, and then execute the change set", "D": "Create a new stack from the updated template and delete the old stack"}, "answers": ["C"], "multi": false, "explanation": "Change set cho phép xem trước resource nào sẽ add/modify/replace trước khi thực thi thay đổi trên stack thật. Đây là cơ chế review và phê duyệt chuẩn cho cập nhật production. Drift detection là để so sánh trạng thái thực tế, không phải xem trước thay đổi template.", "keyword": "CloudFormation change set, preview changes"}, {"n": 3, "text": "A company wants to migrate an on-premises Oracle database to Amazon Aurora PostgreSQL with minimal downtime. The source and target database engines are different, so the schema must be converted as part of the migration. Which combination of services should be used?", "options": {"A": "AWS DataSync and Amazon S3", "B": "AWS Snowball and AWS Storage Gateway", "C": "AWS Schema Conversion Tool (SCT) to convert the schema, and AWS DMS to replicate the data with ongoing replication", "D": "Amazon RDS snapshots and AWS CloudFormation"}, "answers": ["C"], "multi": false, "explanation": "Khi đổi engine (Oracle sang PostgreSQL), SCT chịu trách nhiệm chuyển đổi schema, code và object không tương thích. DMS chịu trách nhiệm nạp dữ liệu và ongoing replication/CDC để giảm downtime khi cutover. DataSync và Snowball không chuyển database theo cơ chế này.", "keyword": "DMS + SCT, heterogeneous migration, CDC"}, {"n": 4, "text": "A gaming company runs a real-time multiplayer game using a custom UDP protocol. Players are in multiple continents and complain about inconsistent latency and packet routing over the public internet. The company also needs two static IP addresses that clients can hard-code. Which service should the company use?", "options": {"A": "Amazon CloudFront with origin shield", "B": "AWS Global Accelerator with a Network Load Balancer endpoint", "C": "Amazon Route 53 latency-based routing to regional EC2 instances", "D": "AWS Direct Connect to each player region"}, "answers": ["B"], "multi": false, "explanation": "Global Accelerator cấp 2 IP tĩnh dạng anycast và định tuyến traffic qua mạng toàn cầu AWS tới endpoint khỏe gần nhất. Nó hỗ trợ cả TCP và UDP nên phù hợp game thời gian thực. CloudFront là CDN cache nội dung HTTP, không dành cho UDP tùy biến.", "keyword": "Global Accelerator, static anycast IP, TCP/UDP"}, {"n": 5, "text": "A company stores audit logs in Amazon S3. The logs are accessed frequently for the first 30 days, rarely for the next 60 days, and must then be retained for 7 years for compliance but are almost never accessed. The company wants the lowest storage cost while meeting these access patterns. What should a solutions architect recommend?", "options": {"A": "Keep all objects in S3 Standard for 7 years", "B": "Use an S3 Lifecycle configuration to transition objects to S3 Standard-IA after 30 days and to S3 Glacier Deep Archive after 90 days", "C": "Transition objects to S3 One Zone-IA after 30 days and delete them after 90 days", "D": "Store the logs on Amazon EBS volumes attached to EC2 instances"}, "answers": ["B"], "multi": false, "explanation": "Lifecycle chuyển tầng theo tuổi dữ liệu giúp tối ưu chi phí: nóng ở Standard, nguội dần sang Standard-IA, lưu trữ lâu dài sang Glacier Deep Archive rẻ nhất. Log phải giữ 7 năm nên không được xóa sau 90 ngày. Giữ tất cả ở Standard sẽ rất tốn kém.", "keyword": "S3 Lifecycle, Standard-IA, Glacier Deep Archive"}, {"n": 6, "text": "A security team discovered that an Amazon S3 bucket was deleted last week. They need to identify who deleted the bucket, when the action occurred, and from which IP address the request came. Which service provides this information?", "options": {"A": "Amazon CloudWatch metrics", "B": "AWS Config configuration history", "C": "AWS CloudTrail event history", "D": "AWS Trusted Advisor"}, "answers": ["C"], "multi": false, "explanation": "CloudTrail ghi lại mọi API call: ai làm, làm gì, khi nào, từ IP nào — đúng câu hỏi \"who did what\". CloudWatch là metrics/logs hiệu năng, Config là lịch sử cấu hình resource. Muốn truy vết hành động xóa bucket phải xem CloudTrail.", "keyword": "CloudTrail, who did what, API activity"}, {"n": 7, "text": "A company wants its applications in a VPC to access an Amazon SQS queue and a partner SaaS application without traffic traversing the public internet. The security team also requires that the traffic stay on the AWS network. Which solutions meet these requirements? (Select TWO.)", "options": {"A": "Create a VPC interface endpoint for Amazon SQS powered by AWS PrivateLink", "B": "Place the EC2 instances in public subnets with Elastic IP addresses", "C": "Use AWS PrivateLink to access the partner SaaS application exposed through a Network Load Balancer", "D": "Create an internet gateway and route all traffic through it for inspection", "E": "Use Amazon CloudFront as a reverse proxy for SQS"}, "answers": ["A", "C"], "multi": true, "explanation": "Interface endpoint dùng PrivateLink giúp traffic tới SQS đi hoàn toàn trong mạng AWS, không qua internet. PrivateLink cũng là cách truy cập dịch vụ SaaS của đối tác được expose qua NLB một cách riêng tư. Các đáp án dùng subnet public/internet gateway đi ngược yêu cầu bảo mật.", "keyword": "PrivateLink, interface endpoint, no internet"}, {"n": 8, "text": "A financial company needs a dedicated, private connection between its data center and AWS with consistent bandwidth and lower latency than an internet-based connection. The connection will carry sensitive workloads permanently. Which solution should the company choose?", "options": {"A": "AWS Site-to-Site VPN over the internet", "B": "AWS Direct Connect", "C": "Amazon CloudFront signed URLs", "D": "VPC peering to the data center"}, "answers": ["B"], "multi": false, "explanation": "Direct Connect là kết nối riêng, chuyên dụng từ data center tới AWS với băng thông ổn định và latency nhất quán. VPN chạy qua internet nên băng thông và độ trễ biến động. Workload tài chính lâu dài, nhạy cảm cần tính ổn định của Direct Connect.", "keyword": "Direct Connect, dedicated private, consistent bandwidth"}, {"n": 9, "text": "A company is releasing a new version of its application to production. It wants to send 10% of user traffic to the new version hosted in a second Region and 90% to the current version, and adjust the proportions gradually. Which Route 53 routing policy should be used?", "options": {"A": "Latency-based routing", "B": "Geolocation routing", "C": "Weighted routing", "D": "Failover routing"}, "answers": ["C"], "multi": false, "explanation": "Weighted routing chia traffic theo trọng số cấu hình, ví dụ 10/90, rất phù hợp canary release và tăng dần tỷ lệ. Latency routing dựa trên độ trễ, geolocation dựa trên vị trí, failover chỉ chuyển khi primary lỗi.", "keyword": "Route 53 weighted routing, canary"}, {"n": 10, "text": "A mobile application has thousands of retail users who sign up with email and password and sign in to access an API. The company does not want to build its own identity store or custom authentication logic. The API is hosted behind Amazon API Gateway. Which authorization mechanism is the MOST appropriate?", "options": {"A": "IAM authorization with SigV4 signed by each retail user", "B": "Amazon Cognito user pool authorizer in API Gateway", "C": "AWS WAF IP allow list", "D": "API keys alone as the authentication mechanism"}, "answers": ["B"], "multi": false, "explanation": "Cognito user pool cung cấp sẵn đăng ký, đăng nhập và quản lý người dùng cuối, tích hợp trực tiếp làm authorizer cho API Gateway. IAM auth phù hợp principal AWS nội bộ, không phù hợp hàng nghìn retail user. API key một mình không phải cơ chế xác thực danh tính.", "keyword": "API Gateway, Cognito user pool authorizer"}, {"n": 11, "text": "A company has 40 VPCs across multiple accounts and needs to connect all VPCs to each other and to an on-premises network through a central hub. Managing individual VPC peering connections has become operationally unmanageable. Which solution provides scalable hub-and-spoke connectivity?", "options": {"A": "Create a full mesh of VPC peering connections", "B": "Use AWS Transit Gateway with route tables to centrally manage connectivity", "C": "Use an internet gateway in each VPC", "D": "Use VPC endpoints between every pair of VPCs"}, "answers": ["B"], "multi": false, "explanation": "Transit Gateway là hub trung tâm kết nối hàng loạt VPC và on-premises, route tập trung, mở rộng tốt. VPC peering là kết nối 1-1, không transitive, số lượng bùng nổ theo mô hình mesh. 40 VPC là dấu hiệu kinh điển phải dùng Transit Gateway.", "keyword": "Transit Gateway, hub-and-spoke, peering limits"}, {"n": 12, "text": "A company requires a disaster recovery strategy in a second Region. A scaled-down but fully functional copy of the production environment must run continuously in the DR Region, and it must be able to scale up quickly during a failover. Recovery time must be faster than a backup-and-restore approach but the company accepts higher cost than pilot light. Which DR strategy is this?", "options": {"A": "Backup and restore", "B": "Pilot light", "C": "Warm standby", "D": "Multi-site active-active"}, "answers": ["C"], "multi": false, "explanation": "Warm standby duy trì một bản sao đầy đủ chức năng nhưng scale nhỏ ở Region DR, sẵn sàng scale up khi failover. Nó nhanh hơn pilot light/backup-restore nhưng rẻ hơn multi-site active-active. RTO tính bằng phút tới giờ tùy mức scale-up.", "keyword": "DR warm standby, scaled-down full copy"}, {"n": 13, "text": "An operations team suspects that someone manually changed a security group rule that was originally deployed by CloudFormation. They need to identify whether the actual state of stack resources differs from the template's expected configuration. What should they use?", "options": {"A": "CloudFormation change sets", "B": "CloudFormation drift detection", "C": "AWS CloudTrail Lake", "D": "Amazon CloudWatch alarms"}, "answers": ["B"], "multi": false, "explanation": "Drift detection so sánh cấu hình thực tế của resource trong stack với cấu hình kỳ vọng trong template. Thay đổi thủ công ngoài CloudFormation sẽ bị phát hiện là drifted. Change set dùng cho thay đổi sắp áp dụng, không phải kiểm tra thay đổi đã xảy ra ngoài quy trình.", "keyword": "CloudFormation drift detection"}, {"n": 14, "text": "A company needs to continuously synchronize 500 TB of file data from an on-premises NFS file system to Amazon S3 for a migration. The synchronization must be automated, handle large-scale transfers efficiently, preserve metadata, and can run over the network on a schedule. Which service is MOST appropriate?", "options": {"A": "AWS DataSync", "B": "AWS Snowball console manual copy", "C": "Amazon S3 Transfer Acceleration with manual uploads", "D": "AWS Storage Gateway Tape Gateway"}, "answers": ["A"], "multi": false, "explanation": "DataSync được thiết kế để di chuyển và đồng bộ dữ liệu file/object quy mô lớn một cách tự động, có lịch trình, kiểm tra toàn vẹn và giữ metadata. Nó phù hợp bài toán sync NFS liên tục sang S3. Snowball là vận chuyển offline, không phải đồng bộ theo lịch qua mạng.", "keyword": "DataSync, large-scale file sync, NFS to S3"}, {"n": 15, "text": "Several EC2 instances have averaged 8% CPU utilization for the past three months. A finance team asks for a data-driven recommendation to rightsize the instances based on actual utilization history. Which AWS tool should be used?", "options": {"A": "AWS Cost Explorer forecasting only", "B": "AWS Compute Optimizer", "C": "AWS Config rules", "D": "Amazon CloudWatch Logs Insights"}, "answers": ["B"], "multi": false, "explanation": "Compute Optimizer phân tích lịch sử utilization thực tế (CPU, memory, network...) để đề xuất rightsize EC2/ASG/Lambda. CPU trung bình 8% trong thời gian dài là tín hiệu oversized rõ ràng. Cost Explorer cho chi phí, không đưa khuyến nghị sizing chuyên sâu như Compute Optimizer.", "keyword": "Compute Optimizer, rightsizing"}, {"n": 16, "text": "Applications running in private subnets must send messages to Amazon SQS. The security policy forbids internet access from these subnets, and there must be no NAT gateway route for this traffic. How can the applications access SQS?", "options": {"A": "Add an internet gateway to the private subnets", "B": "Create a gateway VPC endpoint for SQS", "C": "Create an interface VPC endpoint for SQS using AWS PrivateLink", "D": "Deploy a public proxy EC2 instance in a public subnet"}, "answers": ["C"], "multi": false, "explanation": "SQS dùng interface endpoint (PrivateLink) vì SQS không có gateway endpoint như S3/DynamoDB. Interface endpoint tạo ENI với IP private trong subnet, traffic không cần NAT hay internet. Đây là bẫy hay gặp: chọn nhầm gateway endpoint cho SQS.", "keyword": "Interface endpoint, SQS, PrivateLink"}, {"n": 17, "text": "A compliance team archived objects in S3 Glacier Flexible Retrieval. During an urgent legal investigation, they need to retrieve a small set of objects within a few minutes and are willing to pay a premium for the fastest retrieval. Which retrieval option should they choose?", "options": {"A": "Bulk retrieval", "B": "Standard retrieval", "C": "Expedited retrieval", "D": "S3 Batch Replication"}, "answers": ["C"], "multi": false, "explanation": "Trong Glacier Flexible Retrieval, Expedited là tầng truy xuất nhanh nhất, thường trong vài phút, với chi phí cao nhất. Standard mất vài giờ, Bulk rẻ nhất nhưng chậm nhất và dành cho khối lượng lớn. Nhu cầu khẩn cấp, ít object thì chọn Expedited.", "keyword": "Glacier retrieval, Expedited"}, {"n": 18, "text": "A company wants to protect a production CloudFormation stack from accidental updates or deletions, especially for its stateful RDS resource. Which actions help achieve this? (Select TWO.)", "options": {"A": "Apply a CloudFormation stack policy that denies updates to the protected RDS resource", "B": "Enable termination protection on the stack", "C": "Disable CloudTrail logging for the stack", "D": "Store the template in a public S3 bucket", "E": "Use a change set without reviewing it"}, "answers": ["A", "B"], "multi": true, "explanation": "Stack policy định nghĩa rule allow/deny cho thao tác update trên từng resource, bảo vệ resource stateful như RDS khỏi bị replace/delete ngoài ý muốn. Termination protection ngăn xóa stack. Hai cơ chế bổ sung cho nhau để chống thao tác nhầm trên production.", "keyword": "Stack policy, termination protection"}, {"n": 19, "text": "A startup needs to connect its office to a VPC within a few hours. Cost must be low, the connection will use the public internet, and variable bandwidth and latency are acceptable for now. Which solution meets these requirements?", "options": {"A": "Order a new AWS Direct Connect connection", "B": "Set up an AWS Site-to-Site VPN", "C": "Ship data with AWS Snowball", "D": "Deploy AWS Global Accelerator"}, "answers": ["B"], "multi": false, "explanation": "Site-to-Site VPN thiết lập trong vài giờ, chạy qua internet, chi phí thấp, chấp nhận băng thông biến động. Direct Connect cần đặt circuit và thời gian triển khai dài hơn nhiều. Nhu cầu \"nhanh, rẻ, tạm chấp nhận biến động\" luôn trỏ về VPN.", "keyword": "Site-to-Site VPN, quick and low cost"}, {"n": 20, "text": "A hybrid company runs applications both on premises and in AWS. Workloads in the VPC must resolve on-premises DNS names, and on-premises servers must resolve names in a Route 53 private hosted zone. Which solution provides this bidirectional DNS resolution?", "options": {"A": "Amazon CloudFront DNS routing", "B": "Route 53 Resolver with inbound and outbound endpoints and forwarding rules", "C": "AWS Direct Connect without DNS configuration", "D": "A public hosted zone for all internal names"}, "answers": ["B"], "multi": false, "explanation": "Route 53 Resolver outbound endpoint + forwarding rule cho phép VPC phân giải tên miền on-premises. Inbound endpoint cho phép server on-premises truy vấn private hosted zone trong AWS. Cặp inbound/outbound tạo phân giải DNS hai chiều cho hybrid.", "keyword": "Route 53 Resolver, inbound/outbound endpoint, hybrid DNS"}, {"n": 21, "text": "A news website serves static images, CSS, and JavaScript files to a global audience. Users far from the origin Region experience slow downloads. The company wants to cache this static content close to users and reduce origin load. Which service is BEST suited?", "options": {"A": "AWS Global Accelerator", "B": "Amazon CloudFront", "C": "AWS Transit Gateway", "D": "Elastic Load Balancing"}, "answers": ["B"], "multi": false, "explanation": "CloudFront là CDN cache nội dung tĩnh (ảnh, CSS, JS) tại edge location gần người dùng, giảm latency và giảm tải origin. Global Accelerator không cache nội dung, nó tối ưu đường truyền TCP/UDP tới endpoint. Nội dung tĩnh toàn cầu thì chọn CloudFront.", "keyword": "CloudFront, CDN caching, static content"}, {"n": 22, "text": "A compliance officer needs to be alerted whenever an S3 bucket is created without default encryption enabled, and wants a record of how each bucket's configuration changed over time. Which service should be used?", "options": {"A": "AWS Config with a managed rule for S3 bucket encryption", "B": "Amazon CloudWatch CPU metrics", "C": "AWS CloudTrail user sign-in events only", "D": "AWS Trusted Advisor cost checks"}, "answers": ["A"], "multi": false, "explanation": "AWS Config ghi lại lịch sử cấu hình resource và dùng managed rule để đánh giá compliance liên tục, ví dụ bucket thiếu encryption. Config trả lời câu hỏi \"cấu hình thay đổi như thế nào theo thời gian\". CloudTrail ghi API call, CloudWatch đo metrics — không thay thế Config.", "keyword": "AWS Config, compliance rule, configuration history"}, {"n": 23, "text": "Factory systems on premises generate files that local applications need to access with low latency using standard file protocols, while the company wants the files durably stored in Amazon S3 in the cloud. Which service provides a local file interface backed by S3?", "options": {"A": "AWS DataSync agent only", "B": "Amazon S3 File Gateway (AWS Storage Gateway)", "C": "AWS Snowball Edge", "D": "Amazon EFS cross-Region replication"}, "answers": ["B"], "multi": false, "explanation": "S3 File Gateway của Storage Gateway cung cấp giao diện file (NFS/SMB) ngay tại on-premises, cache dữ liệu nóng tại chỗ và lưu bền vững lên S3. Ứng dụng local vẫn dùng giao thức file quen thuộc. DataSync chỉ đồng bộ, không cung cấp giao diện file thường trực.", "keyword": "Storage Gateway, File Gateway, S3 backend"}, {"n": 24, "text": "A remote research site has collected 80 TB of data. Its internet connection is very slow and unreliable, and transferring the data online would take months. The company needs to move this one-time dataset into Amazon S3. Which solution is MOST appropriate?", "options": {"A": "AWS Site-to-Site VPN", "B": "AWS Snowball", "C": "Amazon CloudFront upload", "D": "Route 53 Resolver endpoints"}, "answers": ["B"], "multi": false, "explanation": "Snowball là dịch vụ vận chuyển vật lý cho dữ liệu lớn khi mạng quá chậm hoặc không đáng tin. 80 TB chuyển online sẽ mất nhiều tháng, trong khi ship thiết bị chỉ mất vài ngày. Đây là tiêu chí kinh điển để phân biệt Snowball với DataSync/VPN.", "keyword": "Snowball, offline transfer, limited bandwidth"}, {"n": 25, "text": "A central networking account created a VPC with shared subnets for application teams in multiple AWS accounts within an organization. Application teams must be able to launch resources into those subnets without each team creating its own VPC. Which service enables this sharing?", "options": {"A": "AWS Resource Access Manager (RAM) to share the subnets", "B": "VPC peering between every application account", "C": "Amazon Route 53 private hosted zones", "D": "AWS CloudFormation StackSets only"}, "answers": ["A"], "multi": false, "explanation": "RAM cho phép chia sẻ tài nguyên AWS xuyên account trong Organization, điển hình là share VPC subnet từ networking account cho application account. Nhờ vậy quản trị mạng tập trung mà team ứng dụng vẫn launch resource được. Peering không tạo cơ chế share subnet.", "keyword": "AWS RAM, shared subnets"}, {"n": 26, "text": "A global application runs identical deployments in three Regions. End users should automatically be directed to the Region that gives them the lowest network latency, based on measurements between the user and each Region. Which Route 53 routing policy should be used?", "options": {"A": "Simple routing", "B": "Weighted routing", "C": "Latency-based routing", "D": "Multivalue answer routing"}, "answers": ["C"], "multi": false, "explanation": "Latency-based routing dùng số đo độ trễ thực tế giữa người dùng và các Region để chọn Region nhanh nhất. Weighted chia theo tỷ lệ cố định, geolocation dựa trên vị trí địa lý theo luật/chính sách. Từ khóa \"lowest latency\" luôn trỏ về latency-based.", "keyword": "Route 53 latency-based routing"}, {"n": 27, "text": "An API uses an external identity provider that is not Amazon Cognito. For each request, custom logic must validate a proprietary token, check tenant permissions stored in a database, and return an IAM policy that API Gateway caches. Which API Gateway authorization mechanism fits best?", "options": {"A": "Cognito user pool authorizer", "B": "Lambda authorizer", "C": "IAM authorization only", "D": "API key validation only"}, "answers": ["B"], "multi": false, "explanation": "Lambda authorizer chạy code tùy biến để validate token độc quyền, tra cứu quyền theo tenant và trả về IAM policy cho API Gateway cache. Cognito authorizer chỉ dùng khi danh tính nằm trong Cognito user pool. IdP bên ngoài + logic tùy biến là dấu hiệu của Lambda authorizer.", "keyword": "API Gateway Lambda authorizer, custom auth"}, {"n": 28, "text": "A company cannot tolerate downtime for its global payment application. It runs the application actively in two Regions, both serving production traffic, with data replicated between Regions so either Region can handle all traffic immediately if the other fails. Which DR strategy gives the lowest RTO and RPO?", "options": {"A": "Backup and restore", "B": "Pilot light", "C": "Warm standby", "D": "Multi-site active-active"}, "answers": ["D"], "multi": false, "explanation": "Multi-site active-active cho RTO/RPO thấp nhất vì cả hai Region đều đang phục vụ traffic thật và dữ liệu được replicate liên tục. Khi một Region lỗi, Region còn lại nhận toàn bộ traffic gần như ngay lập tức. Đổi lại, đây là chiến lược DR tốn kém và phức tạp nhất.", "keyword": "DR multi-site active-active, lowest RTO/RPO"}, {"n": 29, "text": "Which statements correctly describe AWS Global Accelerator? (Select TWO.)", "options": {"A": "It provides two static anycast IP addresses as a fixed entry point for an application", "B": "It routes traffic over the AWS global network to a healthy endpoint close to the user", "C": "It caches HTML and image content at edge locations like a CDN", "D": "It converts database schemas during migration", "E": "It provides a local file interface to Amazon S3"}, "answers": ["A", "B"], "multi": true, "explanation": "Global Accelerator cấp đúng 2 IP anycast tĩnh làm điểm vào cố định và định tuyến qua backbone AWS tới endpoint khỏe gần nhất dựa trên health check. Nó không cache nội dung như CloudFront và không liên quan migration database hay file gateway. Phân biệt GA với CloudFront là điểm thi rất hay gặp.", "keyword": "Global Accelerator, anycast IP, AWS backbone"}, {"n": 30, "text": "VPC A is peered with VPC B, and VPC B is peered with VPC C. Instances in VPC A cannot reach instances in VPC C through VPC B. What explains this behavior and the scalable alternative?", "options": {"A": "VPC peering supports transitive routing; check security groups only", "B": "VPC peering is non-transitive; use AWS Transit Gateway for transitive hub connectivity", "C": "VPC peering requires a NAT gateway in VPC B to forward traffic", "D": "VPC peering works only within the same Availability Zone; move VPC C"}, "answers": ["B"], "multi": false, "explanation": "VPC peering không có tính bắc cầu (non-transitive): A–B và B–C không suy ra A–C. Muốn định tuyến bắc cầu tập trung ở quy mô lớn phải dùng Transit Gateway làm hub. Đây là giới hạn kiến trúc của peering, không phải lỗi security group hay NAT.", "keyword": "VPC peering non-transitive, Transit Gateway"}, {"n": 31, "text": "A web tier must automatically add EC2 instances when average CPU utilization exceeds 70% and remove instances when it falls below 30%. The metric data must come from continuous monitoring of the instances. Which service provides the metrics and alarms to trigger this scaling?", "options": {"A": "AWS CloudTrail", "B": "Amazon CloudWatch", "C": "AWS Config", "D": "AWS Trusted Advisor"}, "answers": ["B"], "multi": false, "explanation": "CloudWatch thu thập metrics như CPUUtilization, tạo alarm và kích hoạt scaling policy cho ASG. CloudTrail ghi API activity, Config ghi cấu hình, Trusted Advisor đưa khuyến nghị — cả ba đều không cung cấp metric/alarm thời gian thực. Bài toán metric + alarm luôn thuộc CloudWatch.", "keyword": "CloudWatch metrics and alarms, auto scaling"}, {"n": 32, "text": "Data in an S3 bucket is 100 TB. Objects are created once and must follow this rule: they cannot transition to S3 Standard-IA until they are at least 30 days old, and storage cost must be minimized for objects older than 90 days that are rarely accessed. A solutions architect configures a lifecycle rule. Which transition sequence respects S3 lifecycle constraints and minimizes cost?", "options": {"A": "Transition to Standard-IA on day 1, then to Glacier Flexible Retrieval on day 10", "B": "Transition to Standard-IA after 30 days, then to Glacier Flexible Retrieval or Glacier Deep Archive after 90 days", "C": "Keep objects in S3 Intelligent-Tiering for 30 days, then delete them", "D": "Transition directly from S3 Standard to Glacier Deep Archive on day 1 for all objects"}, "answers": ["B"], "multi": false, "explanation": "S3 có ràng buộc: object phải ở Standard ít nhất 30 ngày mới được chuyển sang Standard-IA, và các lớp IA/Glacier đều có thời gian lưu tối thiểu. Chuyển sau 30 ngày sang IA rồi sau 90 ngày sang Glacier tuân thủ ràng buộc và giảm chi phí đúng nhịp truy cập. Chuyển ngày 1 hoặc sau 10 ngày vi phạm quy tắc 30 ngày.", "keyword": "S3 Lifecycle constraints, 30-day rule"}, {"n": 33, "text": "A CloudFormation stack policy is attached to a production stack. An engineer attempts to update the stack in a way that would replace the production RDS database instance. The update must be blocked, while other non-critical resources can still be updated. How does the stack policy help?", "options": {"A": "It encrypts the RDS database at rest", "B": "It defines which stack operations are allowed or denied on specific resources during stack updates", "C": "It automatically backs up the database before every update", "D": "It detects drift between the template and actual resources"}, "answers": ["B"], "multi": false, "explanation": "Stack policy là tài liệu JSON gắn với stack, quy định thao tác nào được allow/deny trên resource cụ thể trong lúc stack update. Nhờ đó có thể deny hành động replace RDS production trong khi vẫn cho phép update resource khác. Nó không làm nhiệm vụ backup, encryption hay drift detection.", "keyword": "CloudFormation stack policy, deny update"}, {"n": 34, "text": "A company uses AWS Direct Connect as its primary hybrid connection and requires a backup connection that can take over if Direct Connect fails. The backup must be quick to set up and cost-effective, even if it uses the internet. Which backup solution should be implemented?", "options": {"A": "A second internet gateway", "B": "AWS Site-to-Site VPN as a backup to Direct Connect", "C": "Amazon S3 Transfer Acceleration", "D": "AWS Snowball Edge devices kept on site"}, "answers": ["B"], "multi": false, "explanation": "VPN là phương án dự phòng kinh điển cho Direct Connect: rẻ, dựng nhanh, sẵn sàng nhận traffic khi circuit chính lỗi dù chạy qua internet. Kết hợp DX chính + VPN backup cân bằng giữa ổn định và chi phí. Snowball hay Transfer Acceleration không phải kết nối mạng dự phòng.", "keyword": "Direct Connect backup, VPN failover"}, {"n": 35, "text": "An internal API must only be called by IAM principals from within the same AWS organization. Requests must be signed with AWS Signature Version 4, and no end-user sign-up flow is needed. Which API Gateway authorization type is MOST appropriate?", "options": {"A": "Amazon Cognito user pool authorizer", "B": "Lambda authorizer with a proprietary token", "C": "IAM authorization", "D": "No authorization with a public API"}, "answers": ["C"], "multi": false, "explanation": "IAM authorization yêu cầu request ký bằng SigV4 và kiểm soát truy cập theo IAM principal/policy, rất phù hợp API nội bộ giữa các workload AWS. Không cần luồng đăng ký người dùng cuối như Cognito. Lambda authorizer chỉ cần khi có token/logic tùy biến bên ngoài.", "keyword": "API Gateway IAM authorization, SigV4"}, {"n": 36, "text": "A finance team wants a quick, managed report identifying idle load balancers, underutilized EC2 instances, and unassociated Elastic IP addresses that are increasing the monthly bill. Which AWS service provides these ready-made cost optimization checks?", "options": {"A": "AWS Trusted Advisor", "B": "AWS Config", "C": "Amazon CloudWatch Logs", "D": "AWS CloudFormation"}, "answers": ["A"], "multi": false, "explanation": "Trusted Advisor cung cấp các check có sẵn về cost optimization như idle load balancer, EC2 underutilized, Elastic IP chưa gắn. Đây là báo cáo managed, xem nhanh không cần tự phân tích metrics. Compute Optimizer sâu hơn cho rightsizing compute, còn Trusted Advisor bao quát nhiều loại lãng phí hạ tầng.", "keyword": "Trusted Advisor, cost optimization checks"}, {"n": 37, "text": "A Route 53 geoproximity routing policy is configured for resources in two Regions. The company wants to gradually shift more traffic to the US East Region by expanding its effective geographic area without moving any resources. Which setting should be adjusted?", "options": {"A": "Increase the bias value for the US East record", "B": "Decrease the TTL to zero", "C": "Enable health checks on the US West record only", "D": "Change the routing policy to simple routing"}, "answers": ["A"], "multi": false, "explanation": "Trong geoproximity routing, bias mở rộng hoặc thu hẹp \"vùng ảnh hưởng\" của một resource mà không cần di chuyển resource thật. Tăng bias cho record US East sẽ kéo thêm traffic về Region đó. TTL hay health check không thay đổi phân bổ địa lý theo cách này.", "keyword": "Route 53 geoproximity, bias"}, {"n": 38, "text": "In a secure three-tier architecture, where should each component be placed?", "options": {"A": "Web, application, and database tiers all in public subnets for simplicity", "B": "Load balancer in public subnets, application instances in private subnets, and the database in private subnets with no direct internet route", "C": "Database in a public subnet, application instances in private subnets, and the load balancer in a private subnet", "D": "All tiers in a single private subnet with an internet gateway route"}, "answers": ["B"], "multi": false, "explanation": "Nguyên tắc 3-tier an toàn: chỉ ALB được public để nhận traffic internet, tầng application nằm ở private subnet, database ở private subnet sâu nhất và không có route ra internet. Đặt database ở public subnet là lỗi bảo mật nghiêm trọng thường bị đưa vào đáp án nhiễu. NAT gateway chỉ phục vụ traffic ra có kiểm soát từ private subnet khi cần.", "keyword": "Private subnets, secure 3-tier placement"}, {"n": 39, "text": "A company is migrating a live production database to Amazon RDS using AWS DMS. The source database must remain operational during migration, and changes made after the initial full load must also be replicated to the target to minimize cutover downtime. Which DMS capability should be used?", "options": {"A": "Full load only, performed once", "B": "Full load plus ongoing replication using Change Data Capture (CDC)", "C": "Manual CSV export and import", "D": "S3 Lifecycle transitions"}, "answers": ["B"], "multi": false, "explanation": "DMS full load + CDC giúp migrate database đang chạy thật: nạp toàn bộ dữ liệu ban đầu rồi liên tục áp dụng thay đổi phát sinh. Khi cutover, target đã gần như đồng bộ nên downtime rất ngắn. Full load một lần duy nhất sẽ bỏ lỡ mọi thay đổi sau thời điểm export.", "keyword": "DMS CDC, ongoing replication, minimal downtime"}, {"n": 40, "text": "A company wants to see exactly which service, account, and resource tag caused an unexpected cost spike last month, with a breakdown and filtering by those dimensions. Which tool should the finance team use first?", "options": {"A": "AWS Cost Explorer", "B": "Amazon CloudWatch alarms", "C": "AWS Config timeline", "D": "AWS CloudTrail event history"}, "answers": ["A"], "multi": false, "explanation": "Cost Explorer cho phép phân tích và trực quan chi phí theo service, account, tag, Region... kèm lọc và nhóm tùy ý. Đây là công cụ đầu tiên để truy nguyên spike chi phí. CloudWatch đo hiệu năng, CloudTrail ghi API, Config ghi cấu hình — không phân tích hóa đơn.", "keyword": "Cost Explorer, cost breakdown by tag/service"}, {"n": 41, "text": "Which statements correctly describe AWS Direct Connect compared with a Site-to-Site VPN? (Select TWO.)", "options": {"A": "Direct Connect provides a dedicated private connection with consistent bandwidth", "B": "Direct Connect can be provisioned in minutes over the public internet with no physical connection", "C": "A Site-to-Site VPN runs over the internet and can typically be set up quickly at lower cost", "D": "A Site-to-Site VPN always provides higher and more consistent bandwidth than Direct Connect", "E": "Direct Connect traffic by default provides a public internet path for all users"}, "answers": ["A", "C"], "multi": true, "explanation": "Direct Connect là kết nối vật lý riêng, băng thông nhất quán, cần thời gian triển khai và chi phí cao hơn. VPN chạy qua internet, dựng nhanh trong vài giờ và rẻ, đổi lại hiệu năng biến động. Ghi nhớ cặp đối lập này: DX = riêng/ổn định/chậm triển khai, VPN = internet/nhanh/rẻ.", "keyword": "Direct Connect vs VPN"}, {"n": 42, "text": "An auditor asks: \"What was the exact configuration of this EC2 security group three months ago, and when did its rules change?\" Metrics and API caller identity alone are not enough. Which service answers the auditor's question?", "options": {"A": "Amazon CloudWatch", "B": "AWS CloudTrail", "C": "AWS Config configuration timeline", "D": "AWS Compute Optimizer"}, "answers": ["C"], "multi": false, "explanation": "AWS Config lưu configuration item theo thời gian và có timeline xem lại trạng thái cấu hình tại một thời điểm quá khứ, kèm lịch sử thay đổi. Đây đúng nhu cầu kiểm toán cấu hình 3 tháng trước. CloudTrail cho biết ai gọi API, CloudWatch cho metrics — không tái hiện được toàn bộ cấu hình resource.", "keyword": "AWS Config timeline, configuration history"}, {"n": 43, "text": "A company runs memory-intensive workloads on EC2. Standard CPU-based monitoring did not reveal that the instances are oversized for memory as well as CPU. The company wants recommendations that consider memory utilization collected by an agent. Which service provides these rightsizing recommendations?", "options": {"A": "AWS Compute Optimizer with the CloudWatch agent memory metrics enabled", "B": "AWS Trusted Advisor basic checks only", "C": "Amazon Route 53 health checks", "D": "AWS Storage Gateway metrics"}, "answers": ["A"], "multi": false, "explanation": "Compute Optimizer đưa khuyến nghị rightsizing dựa trên metrics lịch sử, và khi bật CloudWatch agent để thu memory metrics thì khuyến nghị tính cả RAM chứ không chỉ CPU. Workload memory-intensive rất dễ bị oversized nếu chỉ nhìn CPU. Đây là cách tránh mua instance thừa cả CPU lẫn memory.", "keyword": "Compute Optimizer, memory metrics"}, {"n": 44, "text": "A research team needs to restore 50 TB from S3 Glacier Flexible Retrieval for a project starting next week. The data is not urgent, and the team wants the cheapest retrieval option for this large volume. Which retrieval tier should they choose?", "options": {"A": "Expedited retrieval", "B": "Standard retrieval", "C": "Bulk retrieval", "D": "S3 Select on the archived objects in place"}, "answers": ["C"], "multi": false, "explanation": "Bulk retrieval là tầng rẻ nhất của Glacier Flexible Retrieval, thiết kế cho khôi phục khối lượng rất lớn khi thời gian không gấp (thường 5–12 giờ hoặc lâu hơn). Expedited đắt và dành cho khẩn cấp, Standard ở mức trung gian. 50 TB + hạn tuần sau + ưu tiên rẻ thì chọn Bulk.", "keyword": "Glacier retrieval, Bulk cheapest"}, {"n": 45, "text": "A SaaS provider wants to offer its service, hosted behind a Network Load Balancer in its own VPC, privately to customers in their VPCs. Customers should connect using private IP addresses in their own VPCs without VPC peering or internet exposure. Which solution should the provider use?", "options": {"A": "Expose the service with a public Application Load Balancer", "B": "Create a VPC endpoint service powered by AWS PrivateLink", "C": "Share the provider VPC using AWS RAM subnets", "D": "Set up VPC peering with every customer"}, "answers": ["B"], "multi": false, "explanation": "VPC endpoint service kết hợp PrivateLink cho phép nhà cung cấp expose dịch vụ sau NLB của mình cho khách hàng kết nối bằng interface endpoint với IP private. Không cần peering, không lộ internet và không vướng giới hạn trùng CIDR như peering. Đây là mô hình chuẩn để bán dịch vụ private xuyên VPC/account.", "keyword": "PrivateLink endpoint service, NLB"}, {"n": 46, "text": "A company uses Route 53 failover routing for a primary application in one Region and a secondary application in another Region. The secondary must receive traffic only when the primary is unhealthy. What must be configured for this to work correctly?", "options": {"A": "Route 53 health checks associated with the primary record", "B": "S3 Lifecycle rules on the application bucket", "C": "CloudFront origin failover groups only", "D": "Weighted records with equal weights"}, "answers": ["A"], "multi": false, "explanation": "Failover routing chỉ hoạt động đúng khi có health check gắn với record primary để Route 53 biết khi nào primary unhealthy. Khi health check fail, Route 53 tự chuyển truy vấn sang secondary. Thiếu health check thì DNS không có tín hiệu để quyết định failover.", "keyword": "Route 53 failover, health check"}, {"n": 47, "text": "A platform team wants to reuse a proven three-tier design across many applications. The VPC, load balancer, application, and database layers should be deployable as separate reusable units that can be composed and updated independently within CloudFormation. Which approach should the team use?", "options": {"A": "Put every resource for every application into one monolithic template", "B": "Use nested stacks (or modular templates) so each tier is a reusable child stack referenced by a parent stack", "C": "Manually create each tier in the console for flexibility", "D": "Use AWS DMS to replicate the tiers"}, "answers": ["B"], "multi": false, "explanation": "Nested stacks (stack con) cho phép đóng gói từng tier thành module tái sử dụng, parent stack tham chiếu và orchestrate chúng. Mỗi tier có thể được chuẩn hóa, version hóa và tái dùng cho nhiều ứng dụng. Template nguyên khối khổng lồ khó bảo trì và không tái sử dụng được.", "keyword": "CloudFormation nested stacks, reusable tiers"}, {"n": 48, "text": "A company runs steady, always-on compute workloads across EC2, Fargate, and Lambda and wants a discount in exchange for a 1-year commitment to a consistent amount of compute usage, while keeping flexibility to change instance families and Regions. Which purchasing option fits best?", "options": {"A": "Standard Reserved Instances for a specific instance type only", "B": "Compute Savings Plans", "C": "Spot Instances for all workloads", "D": "On-Demand Instances with no commitment"}, "answers": ["B"], "multi": false, "explanation": "Compute Savings Plans cam kết mức chi tiêu compute theo giờ trong 1 hoặc 3 năm và tự áp dụng linh hoạt qua EC2, Fargate, Lambda, đổi được instance family, size và Region. Reserved Instance truyền thống gắn chặt hơn với cấu hình cụ thể. Workload steady + cần linh hoạt là dấu hiệu của Savings Plans.", "keyword": "Compute Savings Plans, flexible commitment"}, {"n": 49, "text": "Access patterns for a large set of S3 objects are unpredictable: some objects are accessed daily, others are untouched for months, and the pattern changes over time. The company wants to minimize storage cost automatically without creating and maintaining lifecycle rules for each pattern. Which S3 storage class should be used?", "options": {"A": "S3 Standard only", "B": "S3 Intelligent-Tiering", "C": "S3 Glacier Deep Archive for all objects", "D": "S3 One Zone-IA for all objects"}, "answers": ["B"], "multi": false, "explanation": "S3 Intelligent-Tiering tự động di chuyển object giữa các access tier dựa trên hành vi truy cập thực tế, có phí giám sát nhỏ nhưng loại bỏ công sức viết lifecycle cho pattern khó đoán. Glacier Deep Archive cho mọi object sẽ gây chậm và tốn phí truy xuất với object đang nóng. Đây là lựa chọn tối ưu khi pattern thay đổi liên tục.", "keyword": "S3 Intelligent-Tiering, unpredictable access"}, {"n": 50, "text": "An Auto Scaling group spans three Availability Zones. When an EC2 instance becomes impaired, the group must automatically terminate it and launch a healthy replacement, maintaining the desired capacity without manual intervention. Which combination enables this?", "options": {"A": "EC2 health checks and Auto Scaling health check replacement", "B": "CloudTrail event notifications sent to an administrator", "C": "Manual scaling scheduled once a week", "D": "S3 versioning and lifecycle expiration"}, "answers": ["A"], "multi": false, "explanation": "ASG dùng health check (EC2 hoặc ELB) để phát hiện instance impaired, tự terminate và launch instance thay thế giữ nguyên desired capacity. Cơ chế này diễn ra tự động, không cần quản trị viên can thiệp. Các đáp án còn lại hoặc thủ công, hoặc không liên quan tới compute health.", "keyword": "Auto Scaling health check replacement"}, {"n": 51, "text": "A VPC interface endpoint for Amazon S3 is used by applications in a VPC. The security team wants to ensure that through this endpoint, users can access only one specific company bucket and no other S3 buckets. What should they configure?", "options": {"A": "A bucket policy on all public buckets", "B": "A VPC endpoint policy attached to the interface endpoint that allows access only to the specific bucket", "C": "A Route 53 private hosted zone for S3", "D": "An internet gateway route with a security group"}, "answers": ["B"], "multi": false, "explanation": "VPC endpoint policy là policy gắn trực tiếp trên endpoint, kiểm soát principal, action và resource được phép đi qua endpoint đó. Giới hạn resource về đúng một bucket ARN sẽ chặn truy cập mọi bucket khác qua endpoint này. Đây là lớp kiểm soát bổ sung cho IAM policy và bucket policy.", "keyword": "VPC endpoint policy, restrict to one bucket"}, {"n": 52, "text": "A cost review finds an AWS account with rising storage and compute charges. Which actions directly reduce cost without harming production workloads? (Select TWO.)", "options": {"A": "Delete unattached EBS volumes and old, unneeded snapshots after verifying they are not required", "B": "Purchase additional On-Demand instances to increase capacity", "C": "Transition infrequently accessed S3 objects to a cheaper storage class using lifecycle rules", "D": "Disable all CloudWatch alarms to save monitoring effort", "E": "Keep idle Elastic IP addresses associated with stopped instances indefinitely"}, "answers": ["A", "C"], "multi": true, "explanation": "EBS volume không gắn và snapshot thừa là lãng phí phổ biến, xóa sau khi kiểm chứng sẽ giảm chi phí storage ngay. Lifecycle chuyển object ít truy cập sang lớp rẻ hơn cũng cắt giảm trực tiếp hóa đơn S3. Giữ Elastic IP idle hoặc mua thêm On-Demand đều làm tăng chi phí.", "keyword": "Cost optimization, delete unattached EBS, S3 lifecycle"}, {"n": 53, "text": "A mining site in a remote location has no reliable connectivity. It needs to collect data locally, run some local compute processing on the device, and later ship the device back to transfer petabyte-scale data into AWS. Which offering is designed for this?", "options": {"A": "AWS Snowball Edge with compute capabilities", "B": "Amazon CloudFront edge locations", "C": "AWS Site-to-Site VPN appliance", "D": "Route 53 Resolver inbound endpoint"}, "answers": ["A"], "multi": false, "explanation": "Snowball Edge ngoài lưu trữ dung lượng lớn còn có khả năng compute tại biên (EC2-compatible/Lambda) cho môi trường mất kết nối. Dữ liệu được xử lý sơ bộ tại chỗ rồi ship thiết bị về AWS để nạp dữ liệu. VPN hay Resolver đều cần kết nối mạng đáng tin cậy — điều địa điểm này không có.", "keyword": "Snowball Edge, edge compute, offline"}, {"n": 54, "text": "A company encrypts its Site-to-Site VPN traffic, and now wants the same IPsec encryption for traffic traversing its AWS Direct Connect connection, which by itself does not provide that encryption over the private circuit. How can this be achieved?", "options": {"A": "Use a public virtual interface with a Site-to-Site VPN running over Direct Connect", "B": "Enable S3 default encryption on a bucket", "C": "Attach a WAF to the Direct Connect gateway", "D": "Use CloudTrail logging for the connection"}, "answers": ["A"], "multi": false, "explanation": "Direct Connect bản chất là mạch riêng nhưng không tự mã hóa IPsec; cách chuẩn là tạo Site-to-Site VPN chạy trên public virtual interface của DX để cộng thêm mã hóa IPsec. Nhờ vậy vẫn giữ đường truyền riêng của DX mà dữ liệu được mã hóa đầu-cuối. Các đáp án còn lại thuộc tầng ứng dụng/log, không mã hóa đường truyền.", "keyword": "VPN over Direct Connect, IPsec encryption"}, {"n": 55, "text": "An enterprise connects its on-premises data center to AWS Transit Gateway using Direct Connect Gateway. Over time it adds dozens of VPCs in multiple accounts. New VPCs should be able to communicate with on-premises networks through the same central gateway without building a new connection for each VPC. What makes this possible?", "options": {"A": "Transit Gateway acts as a central hub; attach each new VPC to the Transit Gateway and update its route tables", "B": "Each VPC requires its own Direct Connect connection by design", "C": "VPC peering between the data center and each VPC", "D": "A NAT instance in every VPC"}, "answers": ["A"], "multi": false, "explanation": "Transit Gateway đóng vai trò hub định tuyến trung tâm: mỗi VPC mới chỉ cần tạo attachment và cấu hình route table của TGW là kết nối được tới on-premises qua Direct Connect Gateway đã có. Không cần kéo circuit riêng cho từng VPC. Đây là lợi thế mở rộng cốt lõi của mô hình hub-and-spoke.", "keyword": "Transit Gateway hub, Direct Connect Gateway"}, {"n": 56, "text": "A UDP-based voice application uses AWS Global Accelerator with endpoint groups in two Regions. If all endpoints in the primary Region become unhealthy, what does Global Accelerator do?", "options": {"A": "It caches voice packets at edge locations until the Region recovers", "B": "It automatically directs traffic to healthy endpoints in the next closest endpoint group based on health checks", "C": "It changes the application's static IP addresses to new addresses", "D": "It converts UDP traffic to HTTP and serves it from CloudFront"}, "answers": ["B"], "multi": false, "explanation": "Global Accelerator liên tục health-check endpoint; khi cả endpoint group chính unhealthy, traffic được chuyển sang endpoint group khỏe ở Region gần nhất tiếp theo. IP anycast tĩnh không thay đổi nên client không cần cấu hình lại. GA không cache nội dung và không chuyển đổi giao thức như CloudFront.", "keyword": "Global Accelerator failover, health check"}, {"n": 57, "text": "A company creates a private API in Amazon API Gateway that must be accessible only from a specific VPC using a VPC endpoint. No requests from the public internet should be allowed, even if the API URL is known. Which combination enforces this?", "options": {"A": "A public API with an API key shared with internal teams", "B": "A private API with a resource policy that allows the VPC endpoint and explicitly denies other sources", "C": "A Cognito authorizer with public sign-up enabled", "D": "CloudFront with a custom origin header"}, "answers": ["B"], "multi": false, "explanation": "Private API chỉ truy cập được qua VPC endpoint được chỉ định, và resource policy phải allow endpoint đó đồng thời deny mọi nguồn khác để chặn cả khi URL bị lộ. API key hay Cognito public không tạo tính private ở tầng mạng. Đây là bộ đôi private API + resource policy thường đi cùng nhau trong đề thi.", "keyword": "Private API, resource policy, VPC endpoint"}, {"n": 58, "text": "A hybrid DNS design uses Amazon Route 53 Resolver. Which components are required for bidirectional resolution between a VPC and an on-premises network? (Select TWO.)", "options": {"A": "A Resolver inbound endpoint in the VPC so on-premises servers can query Route 53 Resolver", "B": "A Resolver outbound endpoint in the VPC plus a forwarding rule so VPC workloads can query on-premises DNS servers", "C": "A CloudFront distribution for DNS queries", "D": "A public S3 bucket hosting zone files", "E": "A Snowball device acting as a DNS server"}, "answers": ["A", "B"], "multi": true, "explanation": "Inbound endpoint nhận truy vấn DNS từ on-premises vào Resolver trong VPC, phục vụ phân giải private hosted zone. Outbound endpoint kèm forwarding rule gửi truy vấn từ VPC ra DNS server on-premises cho tên miền nội bộ của công ty. Thiếu một trong hai chiều, hybrid DNS sẽ không hoàn chỉnh.", "keyword": "Route 53 Resolver, inbound + outbound"}, {"n": 59, "text": "An application writes detailed application logs from EC2 instances. The operations team needs to search these logs, create filters for error patterns, and trigger an alarm when errors exceed a threshold. Which service should be used?", "options": {"A": "Amazon CloudWatch Logs with metric filters and CloudWatch alarms", "B": "AWS Config with configuration rules", "C": "AWS CloudTrail with event selectors only", "D": "Amazon S3 Glacier with vault lock"}, "answers": ["A"], "multi": false, "explanation": "CloudWatch Logs tập trung log ứng dụng, metric filter trích xuất pattern lỗi thành metric, và CloudWatch alarm cảnh báo khi vượt ngưỡng. Đây là chuỗi log → filter → alarm kinh điển của CloudWatch. Config và CloudTrail phục vụ cấu hình và audit API, không phân tích application log theo cách này.", "keyword": "CloudWatch Logs, metric filter, alarm"}, {"n": 60, "text": "For a warm standby DR environment, production data is continuously replicated to an Amazon RDS database in the DR Region, where a smaller application stack is already running. During failover, what are the expected actions?", "options": {"A": "Restore the database from a weekly snapshot and build the entire application stack from scratch", "B": "Promote the replicated database, scale up the DR application capacity, and update Route 53 to direct traffic to the DR Region", "C": "Ship a Snowball device containing the latest data to the DR Region", "D": "Wait for S3 Cross-Region Replication to create the application servers"}, "answers": ["B"], "multi": false, "explanation": "Đặc trưng warm standby là hạ tầng và dữ liệu đã sẵn sàng ở Region DR: database đang replicate, ứng dụng đang chạy ở quy mô nhỏ. Khi failover chỉ cần promote database, scale up ứng dụng và chuyển DNS bằng Route 53 sang DR. Khác hẳn backup-restore phải dựng lại mọi thứ từ snapshot.", "keyword": "Warm standby failover, promote replica, Route 53"}, {"n": 61, "text": "A bucket contains 10 TB of log objects. Keeping them in S3 Standard costs significantly more than in S3 Glacier Flexible Retrieval. The objects are accessed only for audits after 90 days. A manager proposes moving all objects to Glacier Flexible Retrieval on day 1 and retrieving them frequently during the first month for analysis. Why is this proposal flawed, and what is the better approach?", "options": {"A": "Glacier objects cannot ever be retrieved; keep everything in Standard forever", "B": "Frequent early retrievals incur retrieval costs and delays and Glacier is designed for archival access; keep recent logs in Standard or Standard-IA and transition to Glacier after the active analysis period (e.g., after 90 days)", "C": "S3 Glacier Flexible Retrieval is more expensive than Standard for storage; never use it", "D": "Lifecycle transitions happen instantly with no minimum storage duration considerations in any class"}, "answers": ["B"], "multi": false, "explanation": "Glacier được thiết kế cho lưu trữ lạnh: truy xuất chậm, có phí retrieval và thời gian lưu tối thiểu, nên truy cập thường xuyên trong tháng đầu sẽ tốn kém và chậm. Cách đúng là giữ log ở Standard/Standard-IA trong giai đoạn còn phân tích tích cực, rồi mới lifecycle sang Glacier sau khoảng 90 ngày. Đề xuất chuyển ngày 1 bỏ qua hoàn toàn hành vi truy cập thực tế.", "keyword": "Glacier trade-off, retrieval cost, lifecycle timing"}, {"n": 62, "text": "Several departments need access to a shared services VPC and to each other's VPCs only through approved central routing, with strict control over which VPCs can talk to each other. A single VPC peering mesh is rejected. Which design should a solutions architect propose?", "options": {"A": "AWS Transit Gateway with separate route tables to control which attachments can communicate", "B": "One public subnet shared by all departments", "C": "Internet gateways in every VPC with public routes between them", "D": "Amazon S3 as a message bus between VPCs"}, "answers": ["A"], "multi": false, "explanation": "Transit Gateway cho phép dùng nhiều route table riêng để phân đoạn traffic: attachment nào gắn route table nào sẽ chỉ nói chuyện được với các đích được cho phép. Nhờ vậy kiểm soát được ma trận kết nối giữa các phòng ban ở quy mô lớn. Peering mesh không có khả năng kiểm soát tập trung và không bắc cầu.", "keyword": "Transit Gateway route tables, segmentation"}, {"n": 63, "text": "After a product launch, an account's bill doubled in one month. Leadership wants a visual breakdown of costs by service and by linked account for the last 6 months, including trends, without building a custom reporting pipeline. Which service should be used?", "options": {"A": "AWS Cost Explorer", "B": "Amazon CloudWatch dashboards for CPU metrics", "C": "AWS CloudFormation stack events", "D": "AWS Systems Manager inventory"}, "answers": ["A"], "multi": false, "explanation": "Cost Explorer cung cấp sẵn giao diện trực quan phân tích chi phí theo service, linked account, Region, tag trong tối đa 12 tháng kèm xu hướng và forecast cơ bản. Lãnh đạo xem được ngay nguyên nhân hóa đơn tăng mà không cần xây pipeline báo cáo. CloudWatch dashboard chỉ hiển thị metric kỹ thuật, không phải dữ liệu billing.", "keyword": "Cost Explorer, cost by service/account"}, {"n": 64, "text": "Which statements about the relationship between CloudWatch, CloudTrail, and AWS Config are correct? (Select TWO.)", "options": {"A": "CloudWatch monitors performance metrics and logs and can raise alarms", "B": "CloudTrail records API activity showing who did what and when", "C": "AWS Config caches static web content at edge locations", "D": "CloudTrail is a content delivery network for archived logs", "E": "AWS Config is a relational database used for transactional workloads"}, "answers": ["A", "B"], "multi": true, "explanation": "Bộ ba cần phân biệt rõ: CloudWatch = metrics/logs/alarm về hiệu năng và vận hành; CloudTrail = audit trail ghi ai gọi API gì, khi nào; Config = lịch sử và compliance của cấu hình resource. Hai phát biểu A và B mô tả đúng CloudWatch và CloudTrail. Các phát biểu còn lại gán nhầm vai trò CDN/database cho Config và CloudTrail.", "keyword": "CloudWatch vs CloudTrail vs Config"}, {"n": 65, "text": "A company is designing its final production architecture: a three-tier application deployed with CloudFormation across two Regions for disaster recovery, using Direct Connect for hybrid connectivity, S3 lifecycle policies for cost control, and Route 53 health checks for failover. Which combination BEST represents sound architecture across all these areas?", "options": {"A": "Single-AZ EC2 and RDS, manual DNS changes during failover, all data kept in S3 Standard indefinitely, and stack updates applied without review", "B": "Multi-AZ ALB and Auto Scaling group with Multi-AZ RDS in the primary Region, warm standby in the second Region, change sets reviewed before stack updates, Direct Connect with VPN backup, lifecycle transitions to cheaper S3 classes, and Route 53 failover routing driven by health checks", "C": "Public database instances in both Regions, VPC peering between all Regions for transitive routing, and CloudFront used for UDP gaming traffic", "D": "Pilot light with no data replication, Global Accelerator used to cache static images, and Glacier Expedited retrieval used for all routine daily access"}, "answers": ["B"], "multi": false, "explanation": "Đáp án B hội đủ best practice ở mọi lớp: HA Multi-AZ ở Region chính, warm standby cho DR, change set để review trước khi update stack, Direct Connect có VPN dự phòng, lifecycle S3 để giảm chi phí lưu trữ và Route 53 failover theo health check. Các đáp án còn lại đều chứa lỗi kinh điển như single-AZ, database public, nhầm vai trò CloudFront/Global Accelerator hoặc giữ toàn bộ dữ liệu ở Standard.", "keyword": "Capstone architecture, HA + DR + cost + hybrid"}]}};
